  INSERT INTO public.courses (name, description, icon) VALUES
    ('Oracle Cloud Infrastructure Foundations', 'Prepare for the OCI Foundations Associate certification. Covers OCI Intro, IAM, Networking, Compute, Storage, Security, Governance & Administration.', 'cloud')
  INSERT INTO public.subtopics (course_id, name, order_index) VALUES (c1, 'OCI Introduction', 1) RETURNING id INTO s;
  INSERT INTO public.questions (subtopic_id, type, question_text, options, correct_answers, explanation, difficulty) VALUES
    (s, 'mcq', 'Which statement about regions and availability domains is true?', '["Fault domains provide protection against failures across regions.", "All OCI regions have a single availability domain.", "All OCI regions have three availability domains.", "An OCI region has one or more availability domains."]'::jsonb, '[3]'::jsonb, 'An OCI region has one or more availability domains.', 'easy'),
    (s, 'mcq', 'You have subscribed to an OCI region that has one availability domain. You want to deploy a highly available application with two servers and a 2-node database. How would you place the components to maintain the high availability of the application?', '["High availability is not possible as there is only one availability domain in the region.", "Place the servers in one fault domain and the database nodes in another fault domain.", "Place one server and a DB node in one fault domain, and the second server and DB node in another fault domain.", "Place all the components in the same fault domain."]'::jsonb, '[2]'::jsonb, 'Place one server and a DB node in one fault domain, and the second server and DB node in another fault domain.', 'medium'),
    (s, 'mcq', 'Which Oracle Cloud Infrastructure service is NOT intended for a multicloud solution?', '["Oracle Database Service for Azure", "Oracle MySQL HeatWave on AWS", "Oracle Roving Edge Infrastructure", "Oracle Interconnect for Azure"]'::jsonb, '[2]'::jsonb, 'Oracle Roving Edge Infrastructure', 'medium'),
    (s, 'mcq', 'Which capability can be used to protect against failures within an OCI availability domain?', '["Compartments", "Fault Domain", "Load Balancer", "Regions"]'::jsonb, '[1]'::jsonb, 'Fault Domain', 'easy'),
    (s, 'mcq', 'Which statement about OCI is NOT true?', '["A single fault domain can be associated with multiple availability domains within a region.", "An availability domain is one or more data centers located within a region.", "An OCI region is a localized geographic area.", "Availability domains do not share infrastructure, such as power, cooling, or network, within a region."]'::jsonb, '[0]'::jsonb, 'A single fault domain can be associated with multiple availability domains within a region.', 'medium');
  INSERT INTO public.subtopics (course_id, name, order_index) VALUES (c1, 'Identity and Access Management (IAM)', 2) RETURNING id INTO s;
  INSERT INTO public.questions (subtopic_id, type, question_text, options, correct_answers, explanation, difficulty) VALUES
    (s, 'mcq', 'How is a resource in OCI identified?', '["With Compartment Name", "With OCID", "With Username", "With Tenancy ID"]'::jsonb, '[1]'::jsonb, 'With OCID', 'easy'),
    (s, 'mcq', 'Which is NOT a component of OCI Identity and Access Management?', '["Principals", "Network Security Group", "Policies", "Federation"]'::jsonb, '[1]'::jsonb, 'Network Security Group', 'easy'),
    (s, 'mcq', 'Which Identity and Access Management component helps to organize multiple users into a team?', '["Policies", "Groups", "Dynamic Groups", "Compartments"]'::jsonb, '[1]'::jsonb, 'Groups', 'easy'),
    (s, 'mcq', 'Which statement about OCI Identity and Access Management is true?', '["It enables authentication for devices only.", "It enables authorization for on-premises users only.", "It enables you to control access for a group of users.", "It is used to protect information on devices."]'::jsonb, '[2]'::jsonb, 'It enables you to control access for a group of users.', 'easy'),
    (s, 'mcq', 'Which statement about OCI compartments is NOT true?', '["A compartment is a logical collection of related resources.", "It is a best practice to create all your resources in the root compartment.", "Compartments can be nested.", "Compartments help to isolate and control access to resources."]'::jsonb, '[1]'::jsonb, 'It is a best practice to create all your resources in the root compartment.', 'medium');
  INSERT INTO public.subtopics (course_id, name, order_index) VALUES (c1, 'Networking', 3) RETURNING id INTO s;
  INSERT INTO public.questions (subtopic_id, type, question_text, options, correct_answers, explanation, difficulty) VALUES
    (s, 'mcq', 'Which VCN component blocks inbound traffic, but enables outbound traffic to the internet?', '["Dynamic Routing Gateway", "NAT Gateway", "Service Gateway", "Internet Gateway"]'::jsonb, '[1]'::jsonb, 'NAT Gateway', 'easy'),
    (s, 'mcq', 'Which component is NOT created by default with the creation of a Virtual Cloud Network?', '["Default Route Table", "Default DHCP Options", "Default Security List", "Default Local Peering Gateway"]'::jsonb, '[3]'::jsonb, 'Default Local Peering Gateway', 'medium'),
    (s, 'mcq', 'Which statement about Virtual Cloud Network (VCN) peering between two VCNs is NOT valid?', '["A VCN peering connection is a VPN-based connection.", "Peered VCNs can exist in the same OCI region.", "Peered VCNs cannot have overlapping CIDRs.", "Peered VCNs can exist in different OCI regions."]'::jsonb, '[0]'::jsonb, 'A VCN peering connection is a VPN-based connection.', 'medium'),
    (s, 'mcq', 'Which statement about a Virtual Cloud Network (VCN) is true?', '["A VCN can span OCI regions.", "A VCN can reside only in a single region but can span multiple availability domains.", "A VCN can have only one public subnet and more than one private subnet.", "A VCN can be used with only one instance."]'::jsonb, '[1]'::jsonb, 'A VCN can reside only in a single region but can span multiple availability domains.', 'medium'),
    (s, 'mcq', 'Which OSI layer traffic is supported by the OCI Network Load Balancer?', '["Layer 2 (Data Link)", "Layer 7 (Application)", "Layer 5 (Session)", "Layer 4 (Transport)"]'::jsonb, '[3]'::jsonb, 'Layer 4 (Transport)', 'easy');
  INSERT INTO public.subtopics (course_id, name, order_index) VALUES (c1, 'Compute', 4) RETURNING id INTO s;
  INSERT INTO public.questions (subtopic_id, type, question_text, options, correct_answers, explanation, difficulty) VALUES
    (s, 'mcq', 'What is the primary purpose of Oracle Cloud Infrastructure Functions?', '["To provide a managed database service.", "To deploy and manage virtual machines.", "To store and manage files.", "To execute code in response to events or HTTP requests."]'::jsonb, '[3]'::jsonb, 'To execute code in response to events or HTTP requests.', 'easy'),
    (s, 'msq', 'Which two parameters can be customized when creating a flexible shape compute instance? (Select TWO)', '["Number of physical NICs", "Amount of memory", "Number of virtual NICs", "Number of OCPUs"]'::jsonb, '[1,3]'::jsonb, 'Amount of memory, Number of OCPUs', 'medium'),
    (s, 'mcq', 'Which type of storage is associated with instances in the OCI Compute service?', '["File Storage", "Object Storage", "Block Storage", "Archive Storage"]'::jsonb, '[2]'::jsonb, 'Block Storage', 'easy'),
    (s, 'mcq', 'Which statement about the working of autoscaling in an instance pool is true?', '["It automatically changes the shape of the compute instance to increase the number of OCPUs and memory.", "It can perform only metric-based autoscaling.", "It can perform only schedule-based autoscaling.", "It automatically provisions and removes instances in an instance pool."]'::jsonb, '[3]'::jsonb, 'It automatically provisions and removes instances in an instance pool.', 'medium'),
    (s, 'mcq', 'Which processor type is NOT available for the OCI Compute service?', '["AMD", "Intel", "Snapdragon", "Ampere"]'::jsonb, '[2]'::jsonb, 'Snapdragon', 'easy');
  INSERT INTO public.subtopics (course_id, name, order_index) VALUES (c1, 'Storage', 5) RETURNING id INTO s;
  INSERT INTO public.questions (subtopic_id, type, question_text, options, correct_answers, explanation, difficulty) VALUES
    (s, 'mcq', 'You want to store the backup of a database in cloud storage for an extended period at the lowest storage cost. Which object storage tier would you use?', '["Standard", "Premium", "Infrequent Access", "Archive"]'::jsonb, '[3]'::jsonb, 'Archive', 'easy'),
    (s, 'mcq', 'You have an extremely high-performance database workload that requires at least 90 IOPS/GB and 90,000 IOPS per volume. Which OCI Block Volume performance level can be used?', '["Lower Cost", "Balanced", "Ultra High Performance", "Higher Performance"]'::jsonb, '[2]'::jsonb, 'Ultra High Performance', 'hard'),
    (s, 'mcq', 'You have created an Object Storage bucket of Archive tier. Which statement is NOT valid for the Archive Storage tier?', '["From the time a restore request is made, it takes at most an hour to read the data.", "The Archive storage bucket can be upgraded to Standard storage.", "The default time available to download an object after restoration is 24 hours.", "The minimum duration to store objects is 90 days."]'::jsonb, '[1]'::jsonb, 'The Archive storage bucket can be upgraded to Standard storage.', 'medium'),
    (s, 'mcq', 'In the Oracle Cloud Infrastructure Object Storage Service, what is the primary purpose of a pre-authenticated request URL?', '["To enable automatic transition of objects between storage tiers.", "To provide temporary and secure access to a specific object.", "To enable public read access to a specific object.", "To track and monitor object access and usage."]'::jsonb, '[1]'::jsonb, 'To provide temporary and secure access to a specific object.', 'easy'),
    (s, 'mcq', 'What feature of the Oracle Cloud Infrastructure Block Volume service ensures data durability and protection against hardware failures?', '["Compression", "Deduplication", "Replication", "Encryption"]'::jsonb, '[2]'::jsonb, 'Replication', 'medium');
  INSERT INTO public.subtopics (course_id, name, order_index) VALUES (c1, 'Security', 6) RETURNING id INTO s;
  INSERT INTO public.questions (subtopic_id, type, question_text, options, correct_answers, explanation, difficulty) VALUES
    (s, 'mcq', 'Which of the following is NOT a component of the Oracle Cloud Infrastructure Vault service?', '["Master Encryption Key", "Vault", "Secret", "Database Backup"]'::jsonb, '[3]'::jsonb, 'Database Backup', 'easy'),
    (s, 'mcq', 'What is the primary purpose of the Oracle Cloud Infrastructure Vault service?', '["To enforce security best practices in designated compartments.", "To detect, assess, and remediate security risks in your cloud infrastructure.", "To provide security recommendations and insights for your cloud infrastructure.", "To store and manage encryption keys and secrets."]'::jsonb, '[3]'::jsonb, 'To store and manage encryption keys and secrets.', 'easy'),
    (s, 'mcq', 'What is the primary function of a Responder in OCI Cloud Guard?', '["To identify potential issues based on rules.", "To generate compliance audit reports.", "To define the scope of resources Cloud Guard monitors.", "To take corrective action on detected problems."]'::jsonb, '[3]'::jsonb, 'To take corrective action on detected problems.', 'medium'),
    (s, 'mcq', 'What is the main advantage of using OCI Security Zones when deploying resources in your cloud environment?', '["Load balancing across multiple instances.", "Automatic resource scaling.", "Ensuring adherence to security best practices and policies.", "Streamlining application deployment."]'::jsonb, '[2]'::jsonb, 'Ensuring adherence to security best practices and policies.', 'medium'),
    (s, 'mcq', 'In the OCI shared security responsibility model, who is responsible for securing the underlying cloud infrastructure?', '["Oracle", "The customer", "Government agencies", "Third-party vendors"]'::jsonb, '[0]'::jsonb, 'Oracle', 'easy');
  INSERT INTO public.subtopics (course_id, name, order_index) VALUES (c1, 'Governance and Administration', 7) RETURNING id INTO s;
  INSERT INTO public.questions (subtopic_id, type, question_text, options, correct_answers, explanation, difficulty) VALUES
    (s, 'mcq', 'In Oracle Cloud Infrastructure, what is the key difference between service limits and compartment quotas?', '["Both are set and can be modified only by Oracle.", "Service limits are user-defined for compartments, while compartment quotas are set by Oracle for a tenancy or region.", "Both apply only to specific compartments and can be modified only by the user.", "Service limits are set by Oracle for a tenancy or region, while compartment quotas are user-defined for specific compartments."]'::jsonb, '[3]'::jsonb, 'Service limits are set by Oracle for a tenancy or region, while compartment quotas are user-defined for specific compartments.', 'hard'),
    (s, 'mcq', 'Which is NOT a factor that influences pricing in Oracle Cloud Infrastructure?', '["Choice of OCI region", "Data transfer", "Services consumed", "Type of resource"]'::jsonb, '[0]'::jsonb, 'Choice of OCI region', 'medium'),
    (s, 'mcq', 'In Oracle Cloud Infrastructure, what can you set up to receive notifications when budget thresholds are reached?', '["SMS notifications", "Pager alerts", "Push notifications", "Email alerts"]'::jsonb, '[3]'::jsonb, 'Email alerts', 'easy'),
    (s, 'mcq', 'Which type of traffic is charged under data transfer costs in Oracle Cloud Infrastructure?', '["Ingress and egress are charged between instances in different availability domains.", "Egress to the internet is charged.", "Ingress is charged between two availability domains.", "Egress and ingress are both charged to and from the internet."]'::jsonb, '[1]'::jsonb, 'Egress to the internet is charged.', 'medium'),
    (s, 'mcq', 'Which is NOT a supported Oracle Cloud Infrastructure pricing model?', '["Bring Your Own License (BYOL)", "Pay As You Go", "Sovereign subscriptions", "Oracle Universal Credits"]'::jsonb, '[2]'::jsonb, 'Sovereign subscriptions', 'medium');
  INSERT INTO public.courses (name, description, icon) VALUES
    ('Oracle Cloud Infrastructure Architect Associate', 'Detailed skill check review covering OCI Architect concepts: IAM, Load Balancers, Networking, Storage, and Compute.', 'shield')
  INSERT INTO public.subtopics (course_id, name, order_index) VALUES (c2, 'IAM Overview', 1) RETURNING id INTO s;
  INSERT INTO public.questions (subtopic_id, type, question_text, options, correct_answers, explanation, difficulty) VALUES
    (s, 'mcq', 'A company is setting up a new OCI environment and anticipates needing to manage a large number of users with fine-grained access control. It also plans to integrate on-premises or cloud-based Oracle and non-Oracle applications. Which OCI IAM identity domain type best meets these requirements?', '["Premium", "External User", "Free", "Oracle Apps"]'::jsonb, '[0]'::jsonb, 'Premium', 'medium'),
    (s, 'mcq', 'In OCI IAM, which authentication method enables compute instances to access resources securely without storing credentials directly?', '["API keys", "Federated Identity", "OAuth 2.0 tokens", "Instance Principal"]'::jsonb, '[3]'::jsonb, 'Instance Principal', 'medium'),
    (s, 'mcq', 'In the context of OCI IAM and identity domains, what is the primary benefit of using separate domains for employees, business partners, and consumers?', '["Simplified social login integration for consumer applications", "Cost optimization", "Centralized management of all users across the organization", "Improved security and compliance by isolating access privileges for each group"]'::jsonb, '[3]'::jsonb, 'Improved security and compliance by isolating access privileges for each group', 'medium'),
    (s, 'mcq', 'When onboarding users to an OCI IAM identity domain, which of these methods can be leveraged?', '["Synchronization from an external directory, like Active Directory, using directory bridges", "User self-service registration", "All of the options", "Manual user creation only"]'::jsonb, '[2]'::jsonb, 'All of the options', 'easy'),
    (s, 'mcq', 'In the context of OCI IAM and role-based access control (RBAC), how are permissions assigned to users?', '["Permissions are directly assigned to individual users.", "Users inherit permissions based on their membership in groups.", "Permissions are granted based on a user''s job title.", "All users have the same base level of permissions."]'::jsonb, '[1]'::jsonb, 'Users inherit permissions based on their membership in groups.', 'medium');
  INSERT INTO public.subtopics (course_id, name, order_index) VALUES (c2, 'Identity and Access Management – Basics', 2) RETURNING id INTO s;
  INSERT INTO public.questions (subtopic_id, type, question_text, options, correct_answers, explanation, difficulty) VALUES
    (s, 'mcq', 'OCI compartment quotas has three quota policy statements: Set, Unset, and Zero. Which statement removes all access to a specific resource type within a compartment?', '["Zero", "Set", "Unset", "All statements have the same effect."]'::jsonb, '[0]'::jsonb, 'Zero', 'medium'),
    (s, 'mcq', 'How many levels deep can compartments be nested within OCI?', '["Six levels", "Nesting is not supported in OCI.", "Unlimited levels", "Two levels"]'::jsonb, '[0]'::jsonb, 'Six levels', 'easy'),
    (s, 'mcq', 'In OCI IAM policies, verbs such as "inspect," "read," "use," and "manage" are used to:', '["Control the location or compartment where the policy applies.", "Assign a unique identifier for the policy.", "Define the level of permission granted on resources.", "Identify the specific resource type being accessed."]'::jsonb, '[2]'::jsonb, 'Define the level of permission granted on resources.', 'easy'),
    (s, 'mcq', 'By default, which group in the OCI default domain has full access to all OCI Cloud resources?', '["Administrator Group", "Domain Administrator Group", "Security Administrator Group", "Default User Group"]'::jsonb, '[0]'::jsonb, 'Administrator Group', 'easy'),
    (s, 'mcq', 'A company wants to grant a user the ability to create and manage applications within an OCI IAM identity domain, but restrict access to user accounts and security settings. Which predefined administrator role would be MOST appropriate?', '["Application Administrator", "User Administrator", "Help Desk Administrator", "Security Administrator"]'::jsonb, '[0]'::jsonb, 'Application Administrator', 'medium');
  INSERT INTO public.subtopics (course_id, name, order_index) VALUES (c2, 'Identity and Access Management – Advanced', 3) RETURNING id INTO s;
  INSERT INTO public.questions (subtopic_id, type, question_text, options, correct_answers, explanation, difficulty) VALUES
    (s, 'mcq', 'How does a policy reference a network source to control access?', '["By referencing the network source name using request.networkSource.name", "By attaching the network source to the resource itself.", "By specifying the source IP address directly in the policy.", "By using the request.networkSource.id variable in the policy condition."]'::jsonb, '[0]'::jsonb, 'By referencing the network source name using request.networkSource.name.', 'hard'),
    (s, 'mcq', 'How does the "any" keyword function when combining multiple conditions in a policy?', '["Only the first condition within the curly braces is evaluated.", "The \"any\" keyword cannot be used with policy conditions.", "At least one condition within the curly braces must be true for the policy to be true.", "All conditions within the curly braces must be true for the policy to be true."]'::jsonb, '[2]'::jsonb, 'At least one condition within the curly braces must be true for the policy to be true.', 'medium'),
    (s, 'mcq', 'When creating a dynamic group in OCI IAM, what defines the membership criteria?', '["Predefined roles assigned to the group.", "A static list of user accounts.", "Matching rules based on resource type, compartment, or OCID.", "The specific IAM policies assigned to the group."]'::jsonb, '[2]'::jsonb, 'Matching rules based on resource type, compartment, or OCID.', 'medium'),
    (s, 'mcq', 'Tag Based Access Control (TBAC) policies allow you to define conditions based on tags associated with:', '["The requesting user only.", "The target resource only.", "Both the requesting resource (group/compartment) and the target resource.", "None of the above. Tags cannot be used for conditions in TBAC."]'::jsonb, '[2]'::jsonb, 'Both the requesting resource (group/compartment) and the target resource.', 'hard'),
    (s, 'mcq', 'What is the primary benefit of using individual permissions instead of verbs such as "manage" in OCI policies?', '["Simplify policy creation by reducing the number of statements.", "Improve policy readability by separating permissions from resource types.", "Enhance security by enforcing the principle of least privilege.", "Allow automatic assignment of user roles based on compartment location."]'::jsonb, '[2]'::jsonb, 'Enhance security by enforcing the principle of least privilege.', 'hard');
  INSERT INTO public.subtopics (course_id, name, order_index) VALUES (c2, 'Networking – Virtual Cloud Network', 4) RETURNING id INTO s;
  INSERT INTO public.questions (subtopic_id, type, question_text, options, correct_answers, explanation, difficulty) VALUES
    (s, 'mcq', 'Which IP address is invalid?', '["10.0.0.4", "257.10.0.3", "192.168.0.3", "1.1.1.1", "172.16.0.3"]'::jsonb, '[1]'::jsonb, '257.10.0.3', 'easy'),
    (s, 'mcq', 'What happens if you create a VCN with the same CIDR prefix as another VCN in the same tenancy, region, and compartment?', '["Nothing. However, you will not be able to peer them.", "Nothing. However, DNS services will not allow you to create DNS zones.", "You will not be able to add subnets to this VCN.", "OCI will not allow you to create a VCN if another one already has the same CIDR Prefix."]'::jsonb, '[0]'::jsonb, 'Nothing. However, you will not be able to peer them.', 'medium'),
    (s, 'mcq', 'Which gateway is not needed for communicating with resources outside of a VCN?', '["Local Peering Gateway", "Internet Gateway", "NAT Gateway", "Storage Gateway", "Service Gateway"]'::jsonb, '[3]'::jsonb, 'Storage Gateway', 'medium'),
    (s, 'mcq', 'Which CIDR prefix in a VCN can allocate hosts to more resources?', '["/0", "/32", "/16", "/24", "/8"]'::jsonb, '[2]'::jsonb, '/16', 'medium'),
    (s, 'msq', 'Which three statements about Virtual Cloud Network (VCN) are true? (Select THREE)', '["A VCN is a software-defined network, defined in Oracle data centers.", "Each subnet in a VCN can exist in multiple availability domains.", "A VCN cannot connect to another VCN.", "A VCN can reside only in a single region.", "A VCN can reside in multiple regions."]'::jsonb, '[0,1,3]'::jsonb, 'A VCN is a software-defined network, defined in Oracle data centers. Each subnet in a VCN can exist in multiple availability domains. A VCN can reside only in a single region.', 'medium');
  INSERT INTO public.subtopics (course_id, name, order_index) VALUES (c2, 'Networking – IP Management', 5) RETURNING id INTO s;
  INSERT INTO public.questions (subtopic_id, type, question_text, options, correct_answers, explanation, difficulty) VALUES
    (s, 'mcq', 'Which option correctly identifies the types of public IP addresses available in Oracle Cloud Infrastructure?', '["Dedicated and Shared", "Permanent and Temporary", "Ephemeral and Reserved", "Static and Dynamic"]'::jsonb, '[2]'::jsonb, 'Ephemeral and Reserved', 'easy'),
    (s, 'mcq', 'Which option best describes a public IP pool in Oracle Cloud Infrastructure?', '["A collection of IPv6 CIDR blocks allocated to a tenancy.", "A group of IPv6 CIDR blocks available for use by multiple tenancies.", "A set of IPv4 CIDR blocks allocated to a tenancy.", "A group of IPv4 CIDR blocks available for use by multiple tenancies."]'::jsonb, '[2]'::jsonb, 'A set of IPv4 CIDR blocks allocated to a tenancy.', 'hard'),
    (s, 'mcq', 'What is the maximum number of private IPv4 addresses that a VNIC (Virtual Network Interface Card) can have in Oracle Cloud Infrastructure?', '["1", "Unlimited", "32", "33"]'::jsonb, '[3]'::jsonb, '33', 'hard'),
    (s, 'mcq', 'Which option accurately describes the behavior of Reserved Public IP addresses in Oracle Cloud Infrastructure?', '["They can be allocated to any private IP address of a compute instance, float between instances, or be reserved for their tenancy until explicitly deleted.", "They are ephemeral in nature.", "They can only be used for a specific duration and cannot be reserved indefinitely.", "They can only be allocated to specific instances and cannot float between instances."]'::jsonb, '[0]'::jsonb, 'They can be allocated to any private IP address of a compute instance, float between instances, or be reserved for their tenancy until explicitly deleted.', 'medium'),
    (s, 'mcq', 'What is required for importing a public IPv4 CIDR block or IPv6 prefix into Oracle Cloud Infrastructure?', '["Ownership of the public IPv4 CIDR block or IPv6 prefix registered with a Domain Name Registrar.", "Ownership of the public IPv4 CIDR block or IPv6 prefix registered with a Web Hosting Provider.", "Ownership of the public IPv4 CIDR block or IPv6 prefix registered with a Regional Internet Registry (RIR).", "Ownership of the public IPv4 CIDR block or IPv6 prefix registered with a Domain Name System (DNS) Service."]'::jsonb, '[2]'::jsonb, 'Ownership of the public IPv4 CIDR block or IPv6 prefix registered with a Regional Internet Registry (RIR).', 'hard');
  INSERT INTO public.subtopics (course_id, name, order_index) VALUES (c2, 'Networking – Connectivity', 6) RETURNING id INTO s;
  INSERT INTO public.questions (subtopic_id, type, question_text, options, correct_answers, explanation, difficulty) VALUES
    (s, 'mcq', 'Site-to-Site VPN provides two ____________.', '["Dynamic Routing Gateways", "VPN compartments", "FastConnect digital circuits", "VPN tunnels", "CPE devices"]'::jsonb, '[3]'::jsonb, 'VPN tunnels', 'easy'),
    (s, 'mcq', 'A FastConnect Public Virtual Circuit will connect you from on-premises to ____________.', '["The Virtual Cloud Network", "The Remote Peering Connection", "The Oracle Services Network", "The Internet", "Your VPN Tunnels"]'::jsonb, '[2]'::jsonb, 'The Oracle Services Network', 'medium'),
    (s, 'mcq', 'To which OCI gateway do you attach a FastConnect virtual circuit?', '["NAT Gateway", "Local Peering Gateway", "Dynamic Routing Gateway", "Internet Gateway", "Service Gateway"]'::jsonb, '[2]'::jsonb, 'Dynamic Routing Gateway', 'medium'),
    (s, 'mcq', 'A Customer-Premises Equipment is an object that represents a ____________.', '["Compute instance", "Shared secret", "Router on the customer side", "VPN tunnel", "Digital circuit"]'::jsonb, '[2]'::jsonb, 'Router on the customer side', 'easy'),
    (s, 'msq', 'Which three resources can be attached to Dynamic Routing Gateways (DRGs)? (Select THREE)', '["Local Peering Connections", "Site-to-Site VPN IPSec Tunnels", "Remote Peering Connections", "Network Load Balancer", "Virtual Cloud Network"]'::jsonb, '[1,2,4]'::jsonb, 'Site-to-Site VPN IPSec Tunnels, Remote Peering Connections, Virtual Cloud Network', 'hard');
  INSERT INTO public.subtopics (course_id, name, order_index) VALUES (c2, 'Networking – Load Balancer', 7) RETURNING id INTO s;
  INSERT INTO public.questions (subtopic_id, type, question_text, options, correct_answers, explanation, difficulty) VALUES
    (s, 'msq', 'When you create a public load balancer, which two types of IP addresses can you select? (Select TWO)', '["Reserved IPv4 address", "Quad zero IPv4 address", "Ephemeral IPv4 address", "Listener public IPv4 address"]'::jsonb, '[0,2]'::jsonb, 'Reserved IPv4 address, Ephemeral IPv4 address', 'medium'),
    (s, 'mcq', 'In a multi AD region, when selecting a public load balancer, how many AD-specific subnets do you need?', '["Only one", "What you need is VPN.", "You have to use regional subnets.", "At least two, each in different availability domains", "At least two, both in the same Availability Domain"]'::jsonb, '[3]'::jsonb, 'At least two, each in different availability domains', 'medium'),
    (s, 'msq', 'Which three must be configured for a load balancer to accept incoming traffic? (Select THREE)', '["A security list that is open on the listener port", "A route table entry pointing to the listener IP address", "SSL Certificate", "A backend set with at least one backend server", "A listener"]'::jsonb, '[0,3,4]'::jsonb, 'A security list that is open on the listener port, A backend set with at least one backend server, A listener', 'medium'),
    (s, 'mcq', 'In what type of load balancer do you NOT need to specify the bandwidth?', '["An ephemeral load balancer", "A public load balancer", "A network load balancer", "A redundant Site-to-Site VPN", "A private load balancer"]'::jsonb, '[2]'::jsonb, 'A network load balancer', 'easy'),
    (s, 'msq', 'Which three protocols are supported when you use a private network load balancer? (Select THREE)', '["SMTP", "ICMP", "TCP", "UDP", "HTTP"]'::jsonb, '[1,2,3]'::jsonb, 'TCP, UDP, ICMP', 'medium');
  INSERT INTO public.subtopics (course_id, name, order_index) VALUES (c2, 'Networking – DNS Management', 8) RETURNING id INTO s;
  INSERT INTO public.questions (subtopic_id, type, question_text, options, correct_answers, explanation, difficulty) VALUES
    (s, 'mcq', 'Which DNS resolver endpoint do you need for receiving DNS queries from other VCN Resolvers?', '["A listening endpoint", "An on-premises endpoint", "A visual endpoint", "An alias endpoint", "A forwarding endpoint"]'::jsonb, '[0]'::jsonb, 'A listening endpoint', 'medium'),
    (s, 'mcq', 'What Traffic Management Steering Policy do you need for distributing traffic over several servers to optimize performance?', '["Failover", "Geolocation", "IP Prefix Steering", "Load Balancer", "ASN Steering"]'::jsonb, '[3]'::jsonb, 'Load Balancer', 'medium'),
    (s, 'mcq', 'Which DNS record do you use for an IPv6 Address?', '["NS Record", "A Record", "CNAME Record", "ALIAS Record", "AAAA Record"]'::jsonb, '[4]'::jsonb, 'AAAA Record', 'easy'),
    (s, 'mcq', 'What is the purpose of using private views in managing private DNS zones?', '["To logically group a set of private DNS zones", "To restrict access to specific DNS zones", "To accelerate DNS resolution for designated zones", "To encrypt DNS queries and responses"]'::jsonb, '[0]'::jsonb, 'To logically group a set of private DNS zones', 'hard'),
    (s, 'mcq', 'Which record do you need to take to the registrar in case you would like to delegate a DNS zone from your DNS registrar to OCI public DNS?', '["ALIAS Record", "Name Server Record", "A Record", "CNAME Record", "AAAA Record"]'::jsonb, '[1]'::jsonb, 'Name Server Record', 'medium');
  INSERT INTO public.subtopics (course_id, name, order_index) VALUES (c2, 'Networking – Network Command Center', 9) RETURNING id INTO s;
  INSERT INTO public.questions (subtopic_id, type, question_text, options, correct_answers, explanation, difficulty) VALUES
    (s, 'mcq', 'How does the Network Path Analyzer (NPA) identify virtual network configuration issues impacting connectivity?', '["By sending simulated traffic to test network paths.", "By sending actual traffic to test network paths.", "By collecting and analyzing network configuration without sending actual traffic.", "By monitoring physical network infrastructure for anomalies."]'::jsonb, '[2]'::jsonb, 'By collecting and analyzing network configuration without sending actual traffic.', 'medium'),
    (s, 'mcq', 'What are the two types of capture filters that can be created for network monitoring?', '["Flow log capture filters and packet capture filters.", "Flow log capture filters and VTAP capture filters.", "VTAP capture filters and network capture filters.", "Flow control capture filters and traffic capture filters."]'::jsonb, '[1]'::jsonb, 'Flow log capture filters and VTAP capture filters.', 'hard'),
    (s, 'mcq', 'Which service provides a diagram of the implemented topology of all VCNs in a selected region and tenancy?', '["Network Visualizer", "VCN Flow Logs", "Capture Filters", "Network Path Analyzer"]'::jsonb, '[0]'::jsonb, 'Network Visualizer', 'easy'),
    (s, 'mcq', 'You can use the Inter-Region tool to estimate traffic from the Ashburn region to which region?', '["On-premises", "Within Ashburn", "Any other OCI region", "Our FastConnect partners", "Microsoft Azure"]'::jsonb, '[2]'::jsonb, 'Any other OCI region', 'easy'),
    (s, 'mcq', 'Which can serve as a target for traffic mirrored from a VTAP (Virtual Test Access Point) source?', '["A Database system", "A single Compute instance VNIC in a subnet", "A Network Load Balancer", "An Exadata VM Cluster"]'::jsonb, '[2]'::jsonb, 'A Network Load Balancer', 'hard');
  INSERT INTO public.subtopics (course_id, name, order_index) VALUES (c2, 'Compute – Basics', 10) RETURNING id INTO s;
  INSERT INTO public.questions (subtopic_id, type, question_text, options, correct_answers, explanation, difficulty) VALUES
    (s, 'mcq', 'You want to connect to a Linux Instance from a UNIX-style system. Which SSH command would you use to access the instance?', '["ssh -i <public_key_file> <username>@<virtual-ip-address>", "ssh -i <public_key_file> <username>@<public-ip-address>", "ssh -i <public_key_file> <username>@<private-ip-address>", "ssh -i <private_key_file> <username>@<public-ip-address>"]'::jsonb, '[3]'::jsonb, 'ssh -i <private_key_file> <username>@<public-ip-address>', 'easy'),
    (s, 'mcq', 'Which compute shape is designed for hardware-accelerated workloads?', '["Dense I/O Shapes", "Standard Shapes", "GPU Shapes", "Optimized Shapes"]'::jsonb, '[2]'::jsonb, 'GPU Shapes', 'easy'),
    (s, 'mcq', 'You want to run Oracle Cloud Infrastructure (OCI) compute virtual machine instances on dedicated servers that are single tenant and not shared with other customers. Which compute capacity type would you use?', '["Exclusive Virtual Machine Hosts", "Preemptible Instances", "Capacity Reservation", "Dedicated Virtual Machine Hosts"]'::jsonb, '[3]'::jsonb, 'Dedicated Virtual Machine Hosts', 'medium'),
    (s, 'mcq', 'Which statement about Capacity Reservations is NOT correct?', '["You can create, modify, and terminate your capacity reservation at any time.", "Capacity reservations can be shared between availability domains.", "Capacity reservations can have up to 50 capacity configurations.", "Unused reserved capacity is metered differently than used reserved capacity."]'::jsonb, '[1]'::jsonb, 'Capacity reservations can be shared between availability domains.', 'hard'),
    (s, 'mcq', 'You have a workload that is fault-tolerant and can withstand interruptions. Which compute capacity type would you use?', '["Instance Configuration", "Capacity Reservations", "Dedicated Virtual Machine Hosts", "Preemptible Instances"]'::jsonb, '[3]'::jsonb, 'Preemptible Instances', 'easy');
  INSERT INTO public.subtopics (course_id, name, order_index) VALUES (c2, 'Compute – Advanced', 11) RETURNING id INTO s;
  INSERT INTO public.questions (subtopic_id, type, question_text, options, correct_answers, explanation, difficulty) VALUES
    (s, 'mcq', 'Which statement about the Run Command feature is NOT true?', '["On Windows instances, the script runs in a batch shell by default.", "The maximum size for a script file that you upload directly to an instance in plain text is 8 KB.", "On Linux instances, the script runs in a Bash shell by default.", "You can run commands on an instance even when the instance does not have SSH access or open inbound ports."]'::jsonb, '[1]'::jsonb, 'The maximum size for a script file that you upload directly to an instance in plain text is 8 KB.', 'hard'),
    (s, 'mcq', 'You want to encrypt and isolate in-use data and the applications processing that data. Which Oracle Cloud Infrastructure (OCI) offering would you use?', '["Confidential Computing", "Privileged Computing", "Private Computing", "Secret Computing"]'::jsonb, '[0]'::jsonb, 'Confidential Computing', 'medium'),
    (s, 'mcq', 'Which statement about burstable instances is correct?', '["Burstable instances are charged according to the baseline OCPU.", "The baseline utilization is a fraction of each CPU core, either 50% or 75%.", "Burstable instances are designed for scenarios where an instance is not typically idle and has high CPU utilization.", "Burstable instances cost more than regular instances with the same total OCPU count."]'::jsonb, '[0]'::jsonb, 'Burstable instances are charged according to the baseline OCPU.', 'medium'),
    (s, 'mcq', 'You have an instance that cannot be live migrated. OCI schedules a maintenance due date within 14 to 16 days and sends you a notification. What would happen if you do not proactively reboot the instance before the due date?', '["OCI will send you another notification to reboot.", "The instance is either reboot migrated or rebuilt in place for you.", "OCI will terminate the instance.", "OCI does not take any action."]'::jsonb, '[1]'::jsonb, 'The instance is either reboot migrated or rebuilt in place for you.', 'medium'),
    (s, 'msq', 'Which two are the supported types of autoscaling you can apply to an instance pool? (Select TWO)', '["Schedule-based autoscaling", "Metric-based autoscaling", "Time-based autoscaling", "Predictive autoscaling"]'::jsonb, '[0,1]'::jsonb, 'Schedule-based autoscaling, Metric-based autoscaling', 'medium');
  INSERT INTO public.subtopics (course_id, name, order_index) VALUES (c2, 'Object Storage – Basics', 12) RETURNING id INTO s;
  INSERT INTO public.questions (subtopic_id, type, question_text, options, correct_answers, explanation, difficulty) VALUES
    (s, 'mcq', 'Which is NOT a valid storage tier in Object Storage service?', '["Standard", "Archive", "Infrequent Access", "Glacier"]'::jsonb, '[3]'::jsonb, 'Glacier', 'easy'),
    (s, 'mcq', 'You want to upload a 2 TiB object to Object Storage. You would like to have the flexibility of pausing between the uploads of individual parts and resuming the upload when your schedule allows. Which feature should you use?', '["Multipart uploads", "Split upload", "Splitpart uploads", "Simultaneous upload"]'::jsonb, '[0]'::jsonb, 'Multipart uploads', 'easy'),
    (s, 'msq', 'Which two types of object name filters are supported while configuring a lifecycle policy rule in Object Storage service? (Select TWO)', '["Filter matching", "Pattern matching", "Regex matching", "Prefix matching"]'::jsonb, '[1,3]'::jsonb, 'Pattern matching, Prefix matching', 'medium'),
    (s, 'mcq', 'You want Object Storage service to monitor the data access pattern and help you reduce costs by automatically moving objects larger than 1 MiB out of the Standard tier into the more cost-effective Infrequent Access tier. Which feature should you enable?', '["Auto-Tiering", "Auto-Move", "Auto-Transition", "Auto-Change"]'::jsonb, '[0]'::jsonb, 'Auto-Tiering', 'medium'),
    (s, 'mcq', 'You would like to store some data that is seldom accessed but requires long retention periods. Which storage tier should you use to make the solution more cost effective?', '["Infrequent Access", "Archive", "Standard", "Reduced Redundancy"]'::jsonb, '[1]'::jsonb, 'Archive', 'easy');
  INSERT INTO public.subtopics (course_id, name, order_index) VALUES (c2, 'Object Storage – Advanced', 13) RETURNING id INTO s;
  INSERT INTO public.questions (subtopic_id, type, question_text, options, correct_answers, explanation, difficulty) VALUES
    (s, 'mcq', 'Which mechanism provides a way to let users access a bucket or an object without having their own credentials?', '["Pre-Authenticated Requests", "Auth Tokens", "Multipart Uploads", "API Keys"]'::jsonb, '[0]'::jsonb, 'Pre-Authenticated Requests', 'easy'),
    (s, 'msq', 'Which two are valid retention rule types in Oracle Cloud Infrastructure (OCI) Object Storage? (Select TWO)', '["Unlimited", "Time-bound", "Indefinite", "Duration-bound"]'::jsonb, '[1,2]'::jsonb, 'Time-bound, Indefinite', 'hard'),
    (s, 'msq', 'You would like to enable Object Storage replication. Which two statements about a replication policy are correct? (Select TWO)', '["A destination bucket cannot also be a replication source.", "There can be a maximum of one replication policy per source bucket.", "Replication policy creation automatically creates a destination bucket.", "After the replication policy is created, the destination bucket remains in a writable state and you can upload objects directly to it."]'::jsonb, '[0,1]'::jsonb, 'A destination bucket cannot also be a replication source, There can be a maximum of one replication policy per source bucket.', 'hard'),
    (s, 'msq', 'Which two statements about object versioning are correct? (Select TWO)', '["A bucket that is versioning-enabled can have only two versions of an object.", "Object versioning is enabled at the bucket level.", "Object versioning does not increase your storage costs.", "You cannot enable versioning on a bucket with active retention rules."]'::jsonb, '[1,3]'::jsonb, 'Object versioning is enabled at the bucket level, You cannot enable versioning on a bucket with active retention rules.', 'medium'),
    (s, 'mcq', 'You have an object in a bucket. The object was last modified 4 months ago. You create a retention rule and specify a duration of 1 year. Which statement is correct?', '["You will not be able to modify or delete the object for the next 8 months.", "You will not be able to modify or delete the object for the next 12 months.", "You will be able to modify or delete the object for the next 4 months.", "You will be able to modify or delete the object for the next 12 months."]'::jsonb, '[0]'::jsonb, 'You will not be able to modify or delete the object for the next 8 months.', 'medium');
  INSERT INTO public.subtopics (course_id, name, order_index) VALUES (c2, 'Block Storage – Basics', 14) RETURNING id INTO s;
  INSERT INTO public.questions (subtopic_id, type, question_text, options, correct_answers, explanation, difficulty) VALUES
    (s, 'msq', 'Which three are options for access type when you attach a block volume to an instance? (Select THREE)', '["Read/Execute", "Read-only-Shareable", "Read/write", "Read/write-Shareable"]'::jsonb, '[1,2,3]'::jsonb, 'Read-only-Shareable, Read/write, Read/write-Shareable', 'medium'),
    (s, 'mcq', 'Which is NOT a block volume performance level?', '["Lower Cost", "Higher Performance", "Optimized", "Ultra High Performance"]'::jsonb, '[2]'::jsonb, 'Optimized', 'easy'),
    (s, 'mcq', 'What happens when the detached volume autotuning feature is enabled and the volume is detached from the instance?', '["The Block Volume service adjusts the performance level to Higher Performance.", "The Block Volume service adjusts the performance level to Lower Cost.", "The Block Volume service adjusts the performance level to Balanced.", "The Block Volume service adjusts the performance level to Ultra High Performance."]'::jsonb, '[1]'::jsonb, 'The Block Volume service adjusts the performance level to Lower Cost.', 'medium'),
    (s, 'msq', 'Which two are options for attachment type when you attach a block volume to a VM instance? (Select TWO)', '["NFS", "iSCSI", "SMB", "Paravirtualized"]'::jsonb, '[1,3]'::jsonb, 'iSCSI, Paravirtualized', 'medium'),
    (s, 'mcq', 'You want to attach a block volume to a VM instance and one of your requirements is to get better IOPS performance. Which volume attachment type would you use?', '["NFS", "iSCSI", "SMB", "Paravirtualized"]'::jsonb, '[1]'::jsonb, 'iSCSI', 'medium');
  INSERT INTO public.subtopics (course_id, name, order_index) VALUES (c2, 'Block Storage – Advanced', 15) RETURNING id INTO s;
  INSERT INTO public.questions (subtopic_id, type, question_text, options, correct_answers, explanation, difficulty) VALUES
    (s, 'msq', 'Which two statements about volume groups are correct? (Select TWO)', '["You can add up to 32 volumes in a volume group.", "Each volume can be a part of multiple volume groups.", "A volume group can include both boot volumes and block volumes.", "When you delete a volume group, the individual volumes in the group are deleted."]'::jsonb, '[0,2]'::jsonb, 'You can add up to 32 volumes in a volume group, A volume group can include both boot volumes and block volumes.', 'hard'),
    (s, 'mcq', 'You want to make a point-in-time disk-to-disk deep copy of an existing block volume without needing to go through the backup and restore process. What would you create?', '["A clone", "A twin", "A replica", "A prototype"]'::jsonb, '[0]'::jsonb, 'A clone', 'easy'),
    (s, 'mcq', 'Which statement about the OCI Block Volume Cross Region Replication is NOT correct?', '["The replica in the destination region is always billed using the Block Storage Lower Cost option price.", "You can resize a volume with Cross Region Replication enabled.", "It does not cause any downtime or impact on source volumes.", "It performs ongoing automatic asynchronous replication of block volumes to other regions."]'::jsonb, '[1]'::jsonb, 'You can resize a volume with Cross Region Replication enabled.', 'hard'),
    (s, 'msq', 'Which two statements about resizing a block volume are correct? (Select TWO)', '["You can expand an existing volume in place with online resizing.", "You can increase as well as decrease the size of the volume.", "You can restore from a volume backup to a larger volume.", "You can clone an existing volume to a new, smaller volume."]'::jsonb, '[0,2]'::jsonb, 'You can expand an existing volume in place with online resizing, You can restore from a volume backup to a larger volume.', 'medium'),
    (s, 'mcq', 'You would like to make a point-in-time snapshot of the data on a block volume and later restore it as a new volume in a different availability domain within the same region. What would you create?', '["A replica", "A clone", "A backup", "A prototype"]'::jsonb, '[2]'::jsonb, 'A backup', 'easy');
  INSERT INTO public.subtopics (course_id, name, order_index) VALUES (c2, 'File Storage – Basics', 16) RETURNING id INTO s;
  INSERT INTO public.questions (subtopic_id, type, question_text, options, correct_answers, explanation, difficulty) VALUES
    (s, 'mcq', 'Which statement about Oracle Cloud Infrastructure (OCI) File Storage service is correct?', '["You cannot connect to a file system from a bare metal instance.", "The File Storage service supports the Network File System version 3.0 (NFSv3) protocol.", "You cannot access a file system from outside the VCN.", "Storage provisioning is not fully managed."]'::jsonb, '[1]'::jsonb, 'The File Storage service supports the Network File System version 3.0 (NFSv3) protocol.', 'medium'),
    (s, 'mcq', 'Which statement about the OCI File System Export is correct?', '["Each export set contains only one export.", "You cannot delete exports in a mount target.", "The export path is the same as the client mount point path.", "You can add export options to an export to control access to the file system."]'::jsonb, '[3]'::jsonb, 'You can add export options to an export to control access to the file system.', 'medium'),
    (s, 'mcq', 'Which statement about the OCI File System Mount Target is NOT true?', '["File systems are exported through mount targets.", "You cannot reuse the same mount target to make multiple file systems available on the network.", "It provides the IP address or DNS name that is used with a unique export path to mount the file system.", "It is an NFS endpoint that is present in a VCN subnet."]'::jsonb, '[1]'::jsonb, 'You cannot reuse the same mount target to make multiple file systems available on the network.', 'hard'),
    (s, 'mcq', 'Which component uniquely identifies the file system within the mount target, letting you associate many file systems to a single mount target?', '["Export Path", "Mount Point Paths", "Import Path", "Dump Path"]'::jsonb, '[0]'::jsonb, 'Export Path', 'medium'),
    (s, 'mcq', 'Which component represents paths within a client instance to a locally accessible directory to which the remote file system is mounted?', '["Export Path", "Import Path", "Mount Point Path", "Dump Path"]'::jsonb, '[2]'::jsonb, 'Mount Point Path', 'easy');
  INSERT INTO public.subtopics (course_id, name, order_index) VALUES (c2, 'File Storage – Advanced', 17) RETURNING id INTO s;
  INSERT INTO public.questions (subtopic_id, type, question_text, options, correct_answers, explanation, difficulty) VALUES
    (s, 'mcq', 'When a clone is created, the metadata is copied from the source file system to the clone. What do we call that process?', '["Inheritance", "Dehydration", "Hydration", "Depth"]'::jsonb, '[2]'::jsonb, 'Hydration', 'hard'),
    (s, 'mcq', 'You create a file system and then add a 1 GB file. You then take a snapshot of the file system. What would be the total meteredBytes shown by the File Storage service after the hourly update cycle is complete?', '["2 GB", "0.5 GB", "1.5 GB", "1 GB"]'::jsonb, '[3]'::jsonb, '1 GB', 'hard'),
    (s, 'mcq', 'Which statement about File System Replication is NOT correct?', '["Replication Resource is the control component of the replication process.", "Only a file system that has never been exported can be used as a target file system.", "You can replicate the data in one file system to another file system only in the same region.", "You can replicate the data in one file system to another file system in the same region or a different region."]'::jsonb, '[2]'::jsonb, 'You can replicate the data in one file system to another file system only in the same region.', 'hard'),
    (s, 'mcq', 'Which statement about File System Snapshots is NOT correct?', '["Snapshots are a consistent, point-in-time view of your file systems.", "Snapshots are accessible under the root directory of the file system at .target/name.", "The File Storage service encrypts all file system and snapshot data at rest.", "You can take as many snapshots as per your requirement."]'::jsonb, '[1]'::jsonb, 'Snapshots are accessible under the root directory of the file system at .target/name.', 'hard'),
    (s, 'mcq', 'Which package needs to be installed on an instance to enable in-transit encryption with OCI''s File Storage service?', '["oci-growfs", "nfs-utils", "oci-fss-utils", "nfs-common"]'::jsonb, '[2]'::jsonb, 'oci-fss-utils', 'medium');
  INSERT INTO public.courses (name, description, icon) VALUES
    ('Oracle Cloud Infrastructure Networking Professional', 'Advanced OCI network engineering: VCN architectures, Hybrid layouts, DRG routing, DNS, Security and Migration.', 'network')
  INSERT INTO public.subtopics (course_id, name, order_index) VALUES (c3, 'Design And Deploy OCI Virtual Cloud Networks (VCN)', 1) RETURNING id INTO s;
  INSERT INTO public.questions (subtopic_id, type, question_text, options, correct_answers, explanation, difficulty) VALUES
    (s, 'mcq', 'Which RFC 1918 CIDR prefix can be used to create a Virtual Cloud Network (VCN)?', '["10.0.0.0/8", "192.168.0.0/16", "172.16.0.0/12", "0.0.0.0/0", "189.215.154.89/32", "8.8.8.8/8"]'::jsonb, '[1]'::jsonb, '192.168.0.0/16', 'medium'),
    (s, 'mcq', 'Where in Oracle Cloud Infrastructure would you find a key difference between a Network Security Group (NSG) and a Security List (SL)?', '["At the instance level within a subnet", "In the configuration of load balancers", "At the VCN level controlling traffic between subnets", "Within the Identity and Access Management (IAM) console"]'::jsonb, '[2]'::jsonb, 'At the VCN level controlling traffic between subnets', 'hard'),
    (s, 'mcq', 'What is a key distinction between stateful and stateless security rules in Oracle Cloud Infrastructure?', '["Stateful rules track the state of network connections, while stateless rules do not.", "Stateless rules are only applicable to inbound traffic, whereas stateful rules apply to both inbound and outbound traffic.", "Stateless rules are more secure, providing enhanced encryption for data in transit.", "Stateful rules are defined at the VCN level, while stateless rules are defined at the subnet level."]'::jsonb, '[0]'::jsonb, 'Stateful rules track the state of network connections, while stateless rules do not.', 'medium'),
    (s, 'mcq', 'Which Oracle Cloud Infrastructure service enables an instance to connect to a Virtual Cloud Network (VCN) and determines how the instance connects with endpoints inside and outside the VCN?', '["Network Security Group", "Virtual Network Interface Card", "Subnet", "Route Table", "Internet Gateway"]'::jsonb, '[1]'::jsonb, 'Virtual Network Interface Card', 'easy'),
    (s, 'mcq', 'In Oracle Cloud Infrastructure, which service controls the flow of traffic between different network destinations?', '["Identity and Access Management (IAM)", "The Virtual Cloud Network (VCN) Security List", "The Route Table associated with a subnet", "The Network Security Group (NSG) associated with a subnet"]'::jsonb, '[2]'::jsonb, 'The Route Table associated with a subnet', 'easy');
  INSERT INTO public.subtopics (course_id, name, order_index) VALUES (c3, 'VCN Gateways', 2) RETURNING id INTO s;
  INSERT INTO public.questions (subtopic_id, type, question_text, options, correct_answers, explanation, difficulty) VALUES
    (s, 'mcq', 'What is the primary purpose of Oracle Cloud Infrastructure (OCI) private endpoints?', '["To establish private connectivity between a VCN and Oracle Services without using the public internet", "To configure network routing between multiple Virtual Cloud Networks (VCNs)", "To enable direct internet access for resources within a VCN", "To provide secure communication between instances in different subnets within the same VCN"]'::jsonb, '[0]'::jsonb, 'To establish private connectivity between a VCN and Oracle Services without using the public internet', 'medium'),
    (s, 'mcq', 'Your DevOps team needs to interconnect the on-premises network to Oracle Cloud Infrastructure resources, such as a managed database that resides in a private subnet. They indicate that their budget is low and their bandwidth requirements are minimum. You decide that VPN is the best option. They provide you with their router public IP address. You need to create an object in OCI that represents this router. Which object is this?', '["Customer Premises Equipment (CPE)", "Bastion Host", "IPSec Tunnel", "Internet Gateway", "Virtual Network Interface Card (VNIC)", "Dynamic Routing Gateway (DRG)"]'::jsonb, '[0]'::jsonb, 'Customer Premises Equipment (CPE)', 'medium'),
    (s, 'mcq', 'Which Oracle Cloud Infrastructure gateway is specifically designed to connect different Virtual Cloud Networks (VCNs) within the same region?', '["Internet Gateway (IGW)", "Local Peering Gateway (LPG)", "Dynamic Routing Gateway (DRG)", "Network Address Translation (NAT) Gateway"]'::jsonb, '[1]'::jsonb, 'Local Peering Gateway (LPG)', 'easy'),
    (s, 'mcq', 'You, as the company''s cloud architect, have been invited by the CEO to join a staff meeting. The company wants your input on interconnecting Oracle Cloud Infrastructure (OCI) with any of the below four cloud providers in London. They explain to you that they want the resources in the other cloud provider to leverage the ADW machine learning capabilities, that the connection between OCI and the other cloud provider can be provisioned as quickly as possible, and that the connection offers high bandwidth and predictable performance. Which cloud provider would you choose?', '["Digital Ocean", "IBM Cloud", "Google Cloud Platform", "Amazon Web Services"]'::jsonb, '[2]'::jsonb, 'Google Cloud Platform', 'hard'),
    (s, 'mcq', 'Which Oracle Cloud Infrastructure gateway is a stand-alone object that can attach a Virtual Cloud Network (VCN)?', '["Network Address Translation (NAT) Gateway", "Local Peering Gateway (LPG)", "Dynamic Routing Gateway (DRG)", "Internet Gateway (IGW)"]'::jsonb, '[2]'::jsonb, 'Dynamic Routing Gateway (DRG)', 'medium');
  INSERT INTO public.subtopics (course_id, name, order_index) VALUES (c3, 'Plan and Design OCI Networking Solutions and App Services', 3) RETURNING id INTO s;
  INSERT INTO public.questions (subtopic_id, type, question_text, options, correct_answers, explanation, difficulty) VALUES
    (s, 'mcq', 'What is the primary function of Oracle Cloud Infrastructure (OCI) Private DNS?', '["To manage SSL certificates for secure communication within a subnet.", "To provide public domain name resolution for resources within a Virtual Cloud Network (VCN).", "To configure routing tables for private network traffic between different VCNs.", "To enable DNS resolution for resources within a VCN without exposing DNS queries to the public internet."]'::jsonb, '[3]'::jsonb, 'To enable DNS resolution for resources within a VCN without exposing DNS queries to the public internet.', 'medium'),
    (s, 'mcq', 'Assume you have provisioned an Oracle Cloud Infrastructure (OCI) Load Balancer and view it via the Web GUI. What can you use the Move Resource feature for?', '["To convert the Load Balancer to a Network Load Balancer.", "To move the Load Balancer to another region.", "To move the Load Balancer to another compartment.", "To move the Load Balancer to another subnet."]'::jsonb, '[2]'::jsonb, 'To move the Load Balancer to another compartment.', 'easy'),
    (s, 'mcq', 'You are a network administrator configuring a critical application in Oracle Cloud Infrastructure (OCI). The application requires seamless communication over IPv6, and you need to assign your own IPv6 addresses to the resources in the OCI environment. Which OCI service should you use to manage the custom IPv6 addresses and provide routing for your setup?', '["Oracle Cloud FastConnect", "Oracle Cloud Load Balancer", "Oracle Cloud Virtual Network (VCN)", "Oracle Network Path Analyzer"]'::jsonb, '[2]'::jsonb, 'Oracle Cloud Virtual Network (VCN)', 'medium'),
    (s, 'mcq', 'You are responsible for optimizing traffic flow in your Oracle Cloud Infrastructure (OCI) environment and want to implement Traffic Management Steering Policies to direct users to the nearest available instance. Which steering policy in Oracle Cloud Infrastructure Traffic Management should you choose for this purpose?', '["IP Prefix Steering", "Geolocation Steering", "Latency-Based Steering", "Load Balancer Steering"]'::jsonb, '[1]'::jsonb, 'Geolocation Steering', 'medium'),
    (s, 'msq', 'Which three capabilities do you get with Oracle Cloud Infrastructure Public DNS? (Select THREE)', '["Create and manage zones.", "View all zones.", "Create and manage records.", "Create and manage security lists.", "Create and manage IAM policies.", "Create and manage WAF rules."]'::jsonb, '[0,1,2]'::jsonb, 'Create and manage zones. View all zones. Create and manage records.', 'medium'),
    (s, 'mcq', 'You are tasked with configuring a Network Load Balancer (NLB) in Oracle Cloud Infrastructure (OCI) to distribute traffic among a group of backend servers. Your backend servers are hosting a critical application that requires session persistence based on both source and destination IP addresses, source and destination ports, and protocol. Which NLB configuration option should you select to meet this requirement?', '["2-Tuple Hash", "Least Connections", "5-Tuple Hash", "IP Hash"]'::jsonb, '[2]'::jsonb, '5-Tuple Hash', 'hard');
  INSERT INTO public.subtopics (course_id, name, order_index) VALUES (c3, 'Design for Hybrid Networking Architectures', 4) RETURNING id INTO s;
  INSERT INTO public.questions (subtopic_id, type, question_text, options, correct_answers, explanation, difficulty) VALUES
    (s, 'mcq', 'What is the primary purpose of using Border Gateway Protocol (BGP) between your on-premises network and the OCI Virtual Cloud Network (VCN)?', '["To distribute IP addresses to OCI instances", "To secure network communication within the VCN", "To manage security rules for traffic ingress and egress", "To enable dynamic routing and exchange of routes between OCI and on-premises networks"]'::jsonb, '[3]'::jsonb, 'To enable dynamic routing and exchange of routes between OCI and on-premises networks', 'medium'),
    (s, 'mcq', 'Which Dynamic Routing Gateway (DRG) feature involves the propagation of routes between different networks connected to the DRG?', '["Route Tables", "Equal-Cost Multi-Path Routing", "Loopback Attachments", "Route Distributions"]'::jsonb, '[3]'::jsonb, 'Route Distributions', 'hard'),
    (s, 'mcq', 'Which Dynamic Routing Gateway (DRG) feature enables active-active load balancing and failover of network traffic between your Oracle Cloud Infrastructure tenancy and your on-premises resources?', '["Equal-Cost Multi-Path Routing", "Route Tables", "Route Distributions", "Loopback Attachments"]'::jsonb, '[0]'::jsonb, 'Equal-Cost Multi-Path Routing', 'hard'),
    (s, 'mcq', 'You are designing a hybrid cloud solution that involves connecting your on-premises data center to Oracle Cloud Infrastructure (OCI) using a Dynamic Routing Gateway (DRG). For enhanced security, you want to ensure that the traffic passing through the DRG is encrypted. Which OCI service or feature should you leverage to implement encryption for the communication between your on-premises network and OCI via the DRG?', '["Oracle Cloud Site-to-Site VPN", "Oracle Cloud FastConnect", "Oracle Cloud Network Firewall", "Oracle Cloud Remote Peering Connection (RPC)"]'::jsonb, '[0]'::jsonb, 'Oracle Cloud Site-to-Site VPN', 'medium'),
    (s, 'mcq', 'What is a key difference between FastConnect Public Peering and FastConnect Private Peering?', '["FastConnect Public Peering uses a dedicated physical connection, while FastConnect Private Peering uses a shared connection.", "FastConnect Public Peering is more cost-effective for high-traffic workloads, while FastConnect Private Peering is better suited for low-traffic scenarios.", "FastConnect Public Peering provides encryption for data in transit, while FastConnect Private Peering does not.", "FastConnect Public Peering allows access to public Oracle Cloud services, while FastConnect Private Peering provides direct access only to resources within your VCN."]'::jsonb, '[3]'::jsonb, 'FastConnect Public Peering allows access to public Oracle Cloud services, while FastConnect Private Peering provides direct access only to resources within your VCN.', 'hard');
  INSERT INTO public.subtopics (course_id, name, order_index) VALUES (c3, 'Transitive Routing', 5) RETURNING id INTO s;
  INSERT INTO public.questions (subtopic_id, type, question_text, options, correct_answers, explanation, difficulty) VALUES
    (s, 'mcq', 'Which Oracle Cloud Infrastructure gateway is always used in a Transitive Routing Configuration, regardless of the type deployed?', '["Services Gateway", "Local Peering Gateway", "Dynamic Routing Gateway", "NAT Gateway"]'::jsonb, '[2]'::jsonb, 'Dynamic Routing Gateway', 'hard'),
    (s, 'mcq', 'In which Transitive Routing Configuration will the route table include rules that route to a virtual network interface card?', '["Spoke Configuration", "Third-Party Appliance Configuration", "Remote Peering Connection Configuration", "Local Peering Gateway Configuration"]'::jsonb, '[1]'::jsonb, 'Third-Party Appliance Configuration', 'hard'),
    (s, 'mcq', 'Which DRG service provides a list of declarative statements that contain match criteria (such as an OCID) and an action for specifying how routes get imported from or exported to a DRG attachment?', '["Local Peering Attachment", "Route Tables", "Cross-Tenancy Attachments", "Route Distributions"]'::jsonb, '[3]'::jsonb, 'Route Distributions', 'hard'),
    (s, 'mcq', 'The priority of each statement in a route distribution is represented as a number between 1 and 65535. A lower number indicates a higher priority. When a ________ is processed, statements are applied in ascending order defined by their priority. The first rule that matches describes the action that will be taken.', '["route", "distribution", "policy", "attachment"]'::jsonb, '[0]'::jsonb, 'route', 'hard'),
    (s, 'msq', 'Which three OCI gateways can be leveraged for a Transitive Routing Configuration? (Select THREE)', '["Local Peering Gateway", "Internet Gateway", "NAT Gateway", "Services Gateway", "Dynamic Routing Gateway"]'::jsonb, '[0,3,4]'::jsonb, 'Local Peering Gateway, Services Gateway, Dynamic Routing Gateway', 'hard');
  INSERT INTO public.subtopics (course_id, name, order_index) VALUES (c3, 'Implement, and Operate Secure OCI Networking and Connectivity Solutions', 6) RETURNING id INTO s;
  INSERT INTO public.questions (subtopic_id, type, question_text, options, correct_answers, explanation, difficulty) VALUES
    (s, 'mcq', 'What is a key difference between the Dynamic Routing Gateway and Local Peering Gateway when implementing Cross-Tenancy Peering?', '["The Local Peering Gateway can have a Cross-Tenancy Attachment.", "The Dynamic Routing Gateway can have a Cross-Tenancy Attachment.", "The Dynamic Routing Gateway needs the acceptor to be in either tenancy.", "The Local Peering Gateway needs the requestor to be in either tenancy."]'::jsonb, '[1]'::jsonb, 'The Dynamic Routing Gateway can have a Cross-Tenancy Attachment.', 'hard'),
    (s, 'mcq', 'How can you securely access resources in a private subnet using Cloud Shell when the Virtual Cloud Network is located in a region other than the home region?', '["Use a combination of a Public Network Setup and Local Peering Connection.", "Use a Network Load Balancer instead, with the listener on port 22.", "Use a combination of an Ephemeral Private Network Setup and Local Peering Connection.", "Use a combination of an Ephemeral Private Network Setup and Remote Peering Connection."]'::jsonb, '[3]'::jsonb, 'Use a combination of an Ephemeral Private Network Setup and Remote Peering Connection.', 'hard'),
    (s, 'mcq', 'You need to access a Database Node and Virtual Machines that are placed in an isolated private subnet. This private subnet has never had any VCN gateway, and it doesn''t have one currently. What type of session can you use on an OCI Bastion that sits on another subnet within the same VCN?', '["Managed Port Session", "Managed SSH Session", "Port Forwarding Session", "Port Managed Session"]'::jsonb, '[2]'::jsonb, 'Port Forwarding Session', 'medium'),
    (s, 'mcq', 'In an Oracle Cloud Infrastructure (OCI) environment, a company wants to enhance the security of its remote access to private resources within a Virtual Cloud Network (VCN). The company is considering the use of a centralized and secure gateway to access the private resources. Which OCI service is best suited for this scenario?', '["OCI Network Firewall", "Web Application Firewall", "VCN Secure Access Gateway (SAG)", "OCI Bastion"]'::jsonb, '[3]'::jsonb, 'OCI Bastion', 'easy'),
    (s, 'mcq', 'You are responsible for managing your organization''s network security in Oracle Cloud Infrastructure (OCI). You are considering implementing OCI Network Firewall to enhance the security posture. Which statement accurately describes OCI Network Firewall?', '["OCI Network Firewall is a hardware appliance that needs to be installed on-premises to protect the organization''s network.", "OCI Network Firewall is primarily focused on monitoring network traffic.", "OCI Network Firewall is a cloud-native, stateful firewall service that allows you to define and enforce access control policies for traffic flowing in and out of your VCN.", "OCI Network Firewall is a cloud-adjacent, classful firewall service that allows you to define and enforce user access to OCI and on-premises resources."]'::jsonb, '[2]'::jsonb, 'OCI Network Firewall is a cloud-native, stateful firewall service that allows you to define and enforce access control policies for traffic flowing in and out of your VCN.', 'medium');
  INSERT INTO public.subtopics (course_id, name, order_index) VALUES (c3, 'Migrate Workloads to OCI', 7) RETURNING id INTO s;
  INSERT INTO public.questions (subtopic_id, type, question_text, options, correct_answers, explanation, difficulty) VALUES
    (s, 'mcq', 'What is a good solution for moving petabyte-scale datasets from your data center to Object Storage or Archive Storage in Oracle Cloud Infrastructure?', '["Leveraging the Data Transfer Appliance for offline migration", "Leveraging the DNS Load Balancing service between on-premises and Oracle Cloud Infrastructure, gradually changing the ratio between both data centers", "Using Site-to-Site VPN between on-premises and Oracle Cloud Infrastructure, enabling ECMP for active-active configuration, and using Jumbo Frames for your MTU", "Using BYOIP for assigning your on-premises public CIDRs to equivalent resources in Oracle Cloud Infrastructure"]'::jsonb, '[0]'::jsonb, 'Leveraging the Data Transfer Appliance for offline migration', 'medium'),
    (s, 'mcq', 'What is a good way to receive advertisements of all Oracle Cloud Infrastructure Public CIDRs via BGP?', '["By establishing a Public Virtual Circuit between on-premises and OCI via FastConnect and connecting directly to the Oracle Services Network Edge Router", "By establishing a Private Virtual Circuit between on-premises and OCI via FastConnect and connecting directly to the Oracle Services Network Edge Router", "By establishing a Public Virtual Circuit between on-premises and OCI via the FastConnect link and connecting to the Oracle Services Network through the Service Gateway", "By establishing a Private Virtual Circuit between on-premises and OCI via the FastConnect link and connecting to the Oracle Services Network through the Service Gateway"]'::jsonb, '[0]'::jsonb, 'By establishing a Public Virtual Circuit between on-premises and OCI via FastConnect and connecting directly to the Oracle Services Network Edge Router', 'hard');
  INSERT INTO public.subtopics (course_id, name, order_index) VALUES (c3, 'OCI Networking, Connectivity and Troubleshooting Tools', 8) RETURNING id INTO s;
  INSERT INTO public.questions (subtopic_id, type, question_text, options, correct_answers, explanation, difficulty) VALUES
    (s, 'mcq', 'Which Oracle Cloud Infrastructure (OCI) tool helps identify network bottlenecks and latency issues by simulating packet flow along a specified path in your Virtual Cloud Network (VCN)?', '["OCI Network Flow Logs", "OCI Path Analyzer", "OCI Virtual Test Access Point", "OCI Network Visualizer"]'::jsonb, '[1]'::jsonb, 'OCI Path Analyzer', 'easy'),
    (s, 'mcq', 'What is the primary purpose of VCN Flow Logs in Oracle Cloud Infrastructure (OCI)?', '["To monitor the disk usage of instances within a Virtual Cloud Network (VCN)", "To track changes made to Network Security Groups and Route Tables within a Virtual Cloud Network (VCN)", "To automatically configure and manage Load Balancers for optimal traffic distribution", "To capture detailed information about the source and destination of network traffic, including IP addresses, ports, and protocols"]'::jsonb, '[3]'::jsonb, 'To capture detailed information about the source and destination of network traffic, including IP addresses, ports, and protocols', 'medium'),
    (s, 'mcq', 'Why is the Oracle Cloud Infrastructure (OCI) Jovanovac Region in Serbia not listed in the Inter-Region Latency dashboard?', '["The Oracle Services Network does not reach the OCI Jovanovac region. Therefore, it is not possible to monitor the latency with the rest of the OCI regions.", "There is no such region in Oracle Cloud Infrastructure.", "This region exists within a unique realm and Oracle does not provide the tools to connect regions across a realm boundary via the OCI network backbone.", "There are no FastConnect partners in the OCI Jovanovac region."]'::jsonb, '[2]'::jsonb, 'This region exists within a unique realm and Oracle does not provide the tools to connect regions across a realm boundary via the OCI network backbone.', 'hard'),
    (s, 'msq', 'Which two are NOT VTAP components? (Select TWO)', '["VTAP Capture", "Capture Filter", "VTAP Source", "VTAP Target", "VTAP Filter"]'::jsonb, '[0,4]'::jsonb, 'VTAP Capture, VTAP Filter', 'hard'),
    (s, 'mcq', 'As an IT professional managing resources in Oracle Cloud Infrastructure (OCI), you are exploring tools to gain insights into your network architecture and the relationships between different components. Which option accurately describes OCI Network Visualizer?', '["OCI Network Visualizer is a tool that provides a visual representation of your VCN, including subnets, instances, and their interconnections, helping you understand and manage your network topology.", "OCI Network Visualizer is a graphical user interface for managing security groups within an OCI tenancy.", "OCI Network Visualizer is a performance monitoring tool focused on tracking the CPU and memory usage of individual instances within a Virtual Cloud Network (VCN).", "OCI Network Visualizer is a feature that automatically deploys and configures load balancers for optimal traffic distribution in your VCN."]'::jsonb, '[0]'::jsonb, 'OCI Network Visualizer is a tool that provides a visual representation of your VCN, including subnets, instances, and their interconnections, helping you understand and manage your network topology.', 'easy');
  INSERT INTO public.subtopics (course_id, name, order_index) VALUES (c3, 'OCI Networking Best Practices', 9) RETURNING id INTO s;
  INSERT INTO public.questions (subtopic_id, type, question_text, options, correct_answers, explanation, difficulty) VALUES
    (s, 'mcq', 'Why is it a best practice to select the correct subnet type during network design?', '["Because once the subnet is created, you cannot change its type.", "Because your resources might become visible and accessible from the open internet with the default security list.", "Because the Oracle Services Network allows access into the home region only.", "Because some regions only have one availability domain."]'::jsonb, '[0]'::jsonb, 'Because once the subnet is created, you cannot change its type.', 'medium'),
    (s, 'mcq', 'Which Virtual Cloud Network (VCN) component allows customers to implement micro-segmentation?', '["Network Security Groups", "Route Tables", "Private Subnets", "Security Lists"]'::jsonb, '[0]'::jsonb, 'Network Security Groups', 'medium'),
    (s, 'msq', 'What are three reasons for setting up notifications for key network events? (Select THREE)', '["Perform regular failover tests.", "Focus your troubleshooting efforts.", "Quickly audit what changes are made and who is making them.", "Minimize your downtime.", "Prevent IAM breaches to your environment."]'::jsonb, '[1,2,3]'::jsonb, 'Focus your troubleshooting efforts, Quickly audit what changes are made and who is making them, Minimize your downtime.', 'medium'),
    (s, 'mcq', 'What is a best practice when creating a Virtual Cloud Network (VCN)?', '["Avoid BGP ASN overlaps with on-premises Local Area Networks.", "Use the VCN Wizard.", "Avoid CIDR overlaps with other VCNs or on-premises Local Area Networks.", "Create the VCN manually, avoiding the VCN Wizard."]'::jsonb, '[2]'::jsonb, 'Avoid CIDR overlaps with other VCNs or on-premises Local Area Networks.', 'easy'),
    (s, 'mcq', 'Which is a connectivity best practice for ensuring optimal connectivity between Oracle Cloud Infrastructure and on-premises?', '["Verify that ECMP is enabled for active standby connectivity.", "Perform regular failover tests.", "Verify that Dynamic Routing Gateway route tables are capturing the BGP information from on-premises.", "Use a Single FastConnect with a Site-to-Site VPN over it."]'::jsonb, '[1]'::jsonb, 'Perform regular failover tests.', 'medium');
  INSERT INTO public.courses (name, description, icon) VALUES
    ('Oracle AI Autonomous Database Professional', 'Covers Autonomous Database deployment models (Shared & Dedicated), monitoring, scaling, REST APIs, and database migration.', 'database')
  INSERT INTO public.subtopics (course_id, name, order_index) VALUES (c4, 'Getting Started with Autonomous Database', 1) RETURNING id INTO s;
  INSERT INTO public.questions (subtopic_id, type, question_text, options, correct_answers, explanation, difficulty) VALUES
    (s, 'msq', 'Which three statements are true about using Oracle Cloud Infrastructure? (Select THREE)', '["It supports only virtual machine and bare metal DB systems.", "It supports only bare metal DB systems.", "It provides high availability and scalability.", "It supports only Exadata systems.", "It provides complete lifecycle automation.", "It enables you to run everything from small VMs to large bare metal clusters."]'::jsonb, '[2,4,5]'::jsonb, 'It provides high availability and scalability. It provides complete lifecycle automation. It enables you to run everything from small VMs to large bare metal clusters.', 'easy'),
    (s, 'msq', 'Which two statements are true about Autonomous Transaction Processing (ATP)? (Select TWO)', '["Data is stored in row format.", "Missing indexes are detected and created.", "Data is stored in columnar format.", "Complex SQL queries are optimized."]'::jsonb, '[0,1]'::jsonb, 'Data is stored in row format. Missing indexes are detected and created.', 'medium'),
    (s, 'mcq', 'Which type operations are included in automated data center operations?', '["Online backups of a database", "Provisioning a database", "Patching a database", "All of these", "Automatically handling failures and errors"]'::jsonb, '[3]'::jsonb, 'All of these', 'easy'),
    (s, 'msq', 'Which two actions can be performed from the OCI Console for an Oracle Autonomous Database? (Select TWO)', '["Scale up or scale down CPU", "Scale up or scale down memory", "Increase storage allocated for database", "Increase network bandwidth"]'::jsonb, '[0,2]'::jsonb, 'Scale up or scale down CPU, Increase storage allocated for database', 'medium'),
    (s, 'mcq', 'Which statement is true about Autonomous Data Warehouse (ADW)?', '["Response time is optimized for queries.", "Data is stored in row format.", "Data is stored in columnar format.", "Missing indexes are detected and created."]'::jsonb, '[2]'::jsonb, 'Data is stored in columnar format.', 'easy'),
    (s, 'mcq', 'Which statement is true about Autonomous Transaction Processing?', '["Data is stored in columnar format.", "It is used for analytic workloads.", "It is used for OLTP and mixed workloads.", "It is used with data marts and machine learning."]'::jsonb, '[2]'::jsonb, 'It is used for OLTP and mixed workloads.', 'easy');
  INSERT INTO public.subtopics (course_id, name, order_index) VALUES (c4, 'Autonomous Database on Shared Infrastructure', 2) RETURNING id INTO s;
  INSERT INTO public.questions (subtopic_id, type, question_text, options, correct_answers, explanation, difficulty) VALUES
    (s, 'msq', 'Which three capabilities of Oracle Autonomous Database can accelerate innovation? (Select THREE)', '["Provisioning of a data warehouse in seconds", "Instant scaling of storage", "Scaling of CPUs with very little downtime", "Built-in AI and ML to find patterns to identify undiscovered anomalies"]'::jsonb, '[0,1,3]'::jsonb, 'Provisioning of a data warehouse in seconds, Instant scaling of storage, Built-in AI and ML to find patterns to identify undiscovered anomalies', 'medium'),
    (s, 'mcq', 'Which statement is true about Notification Service?', '["It helps you broadcast messages to distributed components by using a hybrid-subscribe model.", "It helps you broadcast messages to distributed components by using an Exadata-subscribe model.", "It helps you broadcast messages to distributed components using a publish-subscribe model.", "It helps you broadcast messages to distributed components by using a private-subscribe model."]'::jsonb, '[2]'::jsonb, 'It helps you broadcast messages to distributed components using a publish-subscribe model.', 'easy'),
    (s, 'mcq', 'Which statement is true about moving Autonomous Database Resources?', '["After a resource is moved to a new compartment, inherent policies apply later and affect access to that resource.", "After a resource is moved to a new compartment, inherent policies apply immediately and affect access to that resource.", "After a resource is moved to a new tenant, inherent policies apply later and affect access to that resource.", "After a resource is moved to a new tenant, inherent policies apply immediately and affect access to that resource."]'::jsonb, '[1]'::jsonb, 'After a resource is moved to a new compartment, inherent policies apply immediately and affect access to that resource.', 'medium'),
    (s, 'msq', 'Which three are required for provisioning an Oracle Autonomous Database instance? (Select THREE)', '["Backup location FRA size", "Database name", "Number of tablespaces", "Workload type", "Number of CPUs"]'::jsonb, '[1,3,4]'::jsonb, 'Database name, Workload type, Number of CPUs', 'medium'),
    (s, 'msq', 'Which two statements are true about a cloned Autonomous Database? (Select TWO)', '["It can contain only the metadata of the source Autonomous Database.", "It can contain only the data of the source Autonomous Database.", "It is a refreshable (read-only) clone of the source Autonomous Database.", "It is a refreshable (read-write) clone of the source Autonomous Database."]'::jsonb, '[1,2]'::jsonb, 'It can contain only the data of the source Autonomous Database, It is a refreshable (read-only) clone of the source Autonomous Database.', 'hard'),
    (s, 'msq', 'Which two are required for Autonomous Database manual backups? (Select TWO)', '["The object bucket name must be in lowercase.", "The name format for the bucket in Object Storage must be backup_<databasename>.", "The object bucket name must be in uppercase.", "The name format for the bucket in Object Storage must be backup#<databasename>."]'::jsonb, '[0,1]'::jsonb, 'The object bucket name must be in lowercase, The name format for the bucket in Object Storage must be backup_<databasename>.', 'hard');
  INSERT INTO public.subtopics (course_id, name, order_index) VALUES (c4, 'Autonomous Database Dedicated', 3) RETURNING id INTO s;
  INSERT INTO public.questions (subtopic_id, type, question_text, options, correct_answers, explanation, difficulty) VALUES
    (s, 'msq', 'At which three levels can you implement isolation with Autonomous Database Dedicated Deployment? (Select THREE)', '["Subnet level", "Database level", "Region level", "Container database level", "Virtual cloud network (VCN) level"]'::jsonb, '[1,3,4]'::jsonb, 'Database level, Container database level, Virtual cloud network (VCN) level', 'hard'),
    (s, 'msq', 'Ideally, which two tasks does a Fleet Administrator perform? (Select TWO)', '["Create IAM users", "Manage Autonomous Databases", "Provision Autonomous Database instances", "Provision autonomous Exadata infrastructure", "Provision autonomous container databases"]'::jsonb, '[3,4]'::jsonb, 'Provision autonomous Exadata infrastructure, Provision autonomous container databases', 'hard'),
    (s, 'msq', 'Which three inputs must you provide when creating an autonomous Exadata infrastructure resource? (Select THREE)', '["VCN", "Storage", "Shape", "Availability domain"]'::jsonb, '[0,2,3]'::jsonb, 'VCN, Shape, Availability domain', 'hard'),
    (s, 'msq', 'Which four levels of access can be defined in policies? (Select FOUR)', '["Inspect", "Manage", "Use", "Create", "Read", "Write"]'::jsonb, '[0,1,2,4]'::jsonb, 'Inspect, Read, Use, Manage', 'easy'),
    (s, 'msq', 'Which three actions can you perform from the Autonomous Container Database (CDB) details page? (Select THREE)', '["Change the backup retention policy for the CDB", "Move the CDB to a different compartment", "Change the maintenance schedule", "Stop the CDB", "Restart the CDB", "Stop the Autonomous Database"]'::jsonb, '[0,1,4]'::jsonb, 'Move the CDB to a different compartment, Change the backup retention policy for the CDB, Restart the CDB', 'hard');
  INSERT INTO public.subtopics (course_id, name, order_index) VALUES (c4, 'Managing and Monitoring Autonomous Database', 4) RETURNING id INTO s;
  INSERT INTO public.questions (subtopic_id, type, question_text, options, correct_answers, explanation, difficulty) VALUES
    (s, 'msq', 'Which three do you need to enter when you set up the config file by using the oci setup config command? (Select THREE)', '["User OCID", "OCI Region OCID", "Tenancy OCID", "File format of the config file", "Location of the config file"]'::jsonb, '[0,2,4]'::jsonb, 'User OCID, Tenancy OCID, Location of the config file', 'medium'),
    (s, 'msq', 'Which two statements are true about REST APIs and RESTful services? (Select TWO)', '["REST APIs use only JSON for communication.", "REST stands for Representational State Transfer.", "REST APIs use the HTTP communication protocol but mainly use JSON for communication.", "RESTful services are complex when compared to traditional XML SOAP communications."]'::jsonb, '[1,2]'::jsonb, 'REST stands for Representational State Transfer, REST APIs use the HTTP communication protocol but mainly use JSON for communication.', 'easy'),
    (s, 'msq', 'Which two statements are true about scaling on demand? (Select TWO)', '["Resizing requires a restart.", "Compute and storage must be scaled together.", "Resizing occurs instantly, and is fully online.", "You can independently scale compute or storage."]'::jsonb, '[2,3]'::jsonb, 'Resizing occurs instantly, and is fully online, You can independently scale compute or storage.', 'medium'),
    (s, 'msq', 'Which two statements are true about the OCI command-line interface (CLI)? (Select TWO)', '["It runs on Linux operating systems only.", "It calls OCI REST APIs.", "It does not use REST APIs.", "It is easy to use but involves complex installation and configuration.", "It is easy to use and lightweight to install."]'::jsonb, '[1,4]'::jsonb, 'It calls OCI REST APIs, It is easy to use and lightweight to install.', 'easy'),
    (s, 'mcq', 'What is the main use case for REST APIs?', '["Monitoring only", "Monitoring and development", "Monitoring and DevOps", "Monitoring, DevOps, and development", "DevOps only"]'::jsonb, '[3]'::jsonb, 'Monitoring, DevOps, and development', 'medium'),
    (s, 'msq', 'Which three statements are true about automated tuning? (Select THREE)', '["Parallel execution of queries needs to be monitored manually.", "It provides fast performance out of the box with zero tuning.", "It has built-in resource management plans.", "Partitioning is not covered as part of the automated tuning.", "It has a simple web-based monitoring console."]'::jsonb, '[1,2,4]'::jsonb, 'It provides fast performance out of the box with zero tuning, It has built-in resource management plans, It has a simple web-based monitoring console.', 'hard');
  INSERT INTO public.subtopics (course_id, name, order_index) VALUES (c4, 'Autonomous Database Tools', 5) RETURNING id INTO s;
  INSERT INTO public.questions (subtopic_id, type, question_text, options, correct_answers, explanation, difficulty) VALUES
    (s, 'msq', 'Which two statements are true about built-in SQL Worksheet and Notebook? (Select TWO)', '["You can quickly start running queries with built-in web-based notebooks.", "You need to install a client query tool for PL/SQL.", "They are based on Apache Tomcat.", "There is no need to install a client query tool."]'::jsonb, '[0,3]'::jsonb, 'You can quickly start running queries with built-in web-based notebooks, There is no need to install a client query tool.', 'easy'),
    (s, 'mcq', 'With which does Oracle Machine Learning allow access to data in Autonomous Database?', '["Data viewing and discovery, and data ingestion and selection", "Data ingestion and selection only", "Data ingestion and selection, and data viewing and discovery", "Data ingestion and selection, data viewing and discovery, and data analysis"]'::jsonb, '[3]'::jsonb, 'Data ingestion and selection, data viewing and discovery, and data analysis', 'medium'),
    (s, 'msq', 'Which two are prerequisites for connecting to an Autonomous Database by using SQL Developer? (Select TWO)', '["Private key", "Listener port number", "Credential wallet", "DB username and password", "Public key", "DB system public IP"]'::jsonb, '[2,3]'::jsonb, 'Credential wallet, DB username and password', 'medium'),
    (s, 'msq', 'Which three actions can a Workspace Administrator perform? (Select THREE)', '["Viewing usage reports for a workspace", "Managing user accounts", "Managing workspace-to-schema assignments", "Approving workspace requests", "Monitoring workspace activity", "Adding space to a schema"]'::jsonb, '[0,1,4]'::jsonb, 'Managing user accounts, Viewing usage reports for a workspace, Monitoring workspace activity', 'hard'),
    (s, 'mcq', 'Which statement is true about a workspace in Oracle APEX?', '["It can be associated with multiple schemas from different databases.", "It is not associated with any schemas.", "It can be associated with only one schema.", "It can be associated with multiple schemas in the same database."]'::jsonb, '[3]'::jsonb, 'It can be associated with multiple schemas in the same database.', 'hard');
  INSERT INTO public.subtopics (course_id, name, order_index) VALUES (c4, 'Developing on Autonomous Database', 6) RETURNING id INTO s;
  INSERT INTO public.questions (subtopic_id, type, question_text, options, correct_answers, explanation, difficulty) VALUES
    (s, 'mcq', 'Which clause is used in Property Graph query language to specify patterns?', '["Between", "Distinct", "Like", "Match"]'::jsonb, '[3]'::jsonb, 'Match', 'medium'),
    (s, 'mcq', 'Which statement is true about Spatial Studio?', '["It does not need additional resources.", "It is a fully managed service available in OCI.", "It comes with an Autonomous Database at an additional cost.", "It is a self-service application to create interactive maps."]'::jsonb, '[3]'::jsonb, 'It is a self-service application to create interactive maps.', 'medium'),
    (s, 'mcq', 'You want to move some unstructured data consisting of images and videos to Cloud Storage. Which type of storage is the most cost-effective?', '["Archive Storage", "Block Volume", "File Storage", "Object Storage"]'::jsonb, '[3]'::jsonb, 'Object Storage', 'easy'),
    (s, 'msq', 'Which two statements are true about Oracle Text? (Select TWO)', '["It supports PDFs only.", "It provides full-text content searching.", "It renders search results in HTML format only.", "It combines relational content searching via SQL."]'::jsonb, '[1,3]'::jsonb, 'It provides full-text content searching, It combines relational content searching via SQL.', 'hard'),
    (s, 'msq', 'Which two statements are true about Oracle Autonomous JSON Database? (Select TWO)', '["It supports MySQL-style database applications.", "It allows you to store JSON data in the database.", "It supports NoSQL-style document-centric applications.", "It does not support autoscaling."]'::jsonb, '[1,2]'::jsonb, 'It allows you to store JSON data in the database, It supports NoSQL-style document-centric applications.', 'medium');
  INSERT INTO public.subtopics (course_id, name, order_index) VALUES (c4, 'Migration', 7) RETURNING id INTO s;
  INSERT INTO public.questions (subtopic_id, type, question_text, options, correct_answers, explanation, difficulty) VALUES
    (s, 'msq', 'For which three cloud services does DBMS_CLOUD provide support for loading data from files to tables in Autonomous Database? (Select THREE)', '["OCI Object Storage Classic", "OCI Object Storage", "IBM Spectrum Storage", "Amazon AWS S3", "Dell EMC Elastic Cloud Storage"]'::jsonb, '[0,1,3]'::jsonb, 'OCI Object Storage Classic, OCI Object Storage, Amazon AWS S3', 'medium'),
    (s, 'msq', 'Which two methods can you use to migrate an on-premises database to Oracle Autonomous Database? (Select TWO)', '["GoldenGate", "Data Pump", "RMAN", "Data Guard"]'::jsonb, '[0,1]'::jsonb, 'GoldenGate, Data Pump', 'medium'),
    (s, 'mcq', 'What does the Database Migration service use for migration?', '["Data Guard", "Backup Cloud Module", "GoldenGate", "RMAN Backup"]'::jsonb, '[2]'::jsonb, 'GoldenGate', 'hard'),
    (s, 'mcq', 'Which procedure do you use to load data directly into existing Autonomous Database tables?', '["DBMS_CLOUD.COPY_DATA", "DBMS_CLOUD.CREATE_EXTERNAL_TABLE", "DBMS_CLOUD.LIST_FILES", "DBMS_CLOUD.PUT_OBJECT"]'::jsonb, '[0]'::jsonb, 'DBMS_CLOUD.COPY_DATA', 'medium');
  INSERT INTO public.courses (name, description, icon) VALUES
    ('Oracle Cloud Infrastructure DevOps Professional', 'CI/CD practices, build pipelines, deployment configurations, integration, and monitoring on OCI.', 'terminal')
  INSERT INTO public.subtopics (course_id, name, order_index) VALUES (c5, 'DevOps Concepts and OCI Resources', 1) RETURNING id INTO s;
  INSERT INTO public.questions (subtopic_id, type, question_text, options, correct_answers, explanation, difficulty) VALUES
    (s, 'mcq', 'What is the primary purpose of OCI DevOps service?', '["To manage Oracle database systems.", "To run machine learning models.", "To automate the software development lifecycle on OCI.", "To monitor network performance."]'::jsonb, '[2]'::jsonb, 'To automate the software development lifecycle on OCI.', 'easy'),
    (s, 'mcq', 'Which OCI DevOps resource represents a source code repository?', '["Build Pipeline", "Deploy Artifact", "Code Repository", "Connection"]'::jsonb, '[2]'::jsonb, 'Code Repository', 'easy'),
    (s, 'mcq', 'What type of connection can be configured to mirror external repositories in OCI DevOps?', '["FTP", "GitHub/GitLab", "JDBC", "Telnet"]'::jsonb, '[1]'::jsonb, 'GitHub/GitLab', 'medium'),
    (s, 'mcq', 'Which OCI DevOps component is used to manage binaries, container images, or deployment manifests?', '["Project", "Artifact", "Triggers", "Environments"]'::jsonb, '[1]'::jsonb, 'Artifact', 'easy'),
    (s, 'mcq', 'What is required to allow OCI DevOps to access other resources in the tenancy?', '["IAM Policies and Dynamic Groups", "Standard user login", "API key stored in compute", "No authentication required"]'::jsonb, '[0]'::jsonb, 'IAM Policies and Dynamic Groups', 'medium');
  INSERT INTO public.subtopics (course_id, name, order_index) VALUES (c5, 'Build Pipelines', 2) RETURNING id INTO s;
  INSERT INTO public.questions (subtopic_id, type, question_text, options, correct_answers, explanation, difficulty) VALUES
    (s, 'mcq', 'What defines the steps executed during a build stage in OCI DevOps?', '["A JSON config block", "A buildspec YAML file", "An XML deployment descriptor", "A bash script on the local machine"]'::jsonb, '[1]'::jsonb, 'A buildspec YAML file', 'medium'),
    (s, 'mcq', 'Which build stage is used to run tests and compile code?', '["Deliver Artifacts", "Trigger Deployment", "Managed Build", "Manual Approval"]'::jsonb, '[2]'::jsonb, 'Managed Build', 'easy'),
    (s, 'mcq', 'How can a build pipeline be triggered automatically?', '["Using webhooks on repository commits", "Manually by the administrator only", "By sending an email to OCI support", "Using cron jobs inside the database"]'::jsonb, '[0]'::jsonb, 'Using webhooks on repository commits', 'medium'),
    (s, 'mcq', 'Which stage in a build pipeline is responsible for pushing compiled binaries to the Artifact Registry?', '["Managed Build", "Deliver Artifacts", "Trigger Deployment", "Verify Security"]'::jsonb, '[1]'::jsonb, 'Deliver Artifacts', 'medium'),
    (s, 'mcq', 'What shape type does the OCI DevOps service use for running build runners by default?', '["Standard VM shapes", "Flexible shapes or default managed shapes", "Bare metal DB instances", "Compute capacity reservations"]'::jsonb, '[1]'::jsonb, 'Flexible shapes or default managed shapes', 'medium');
  INSERT INTO public.subtopics (course_id, name, order_index) VALUES (c5, 'Deploy Pipelines', 3) RETURNING id INTO s;
  INSERT INTO public.questions (subtopic_id, type, question_text, options, correct_answers, explanation, difficulty) VALUES
    (s, 'mcq', 'Which environment is NOT a supported deploy target in OCI DevOps?', '["OCI Container Engine for Kubernetes (OKE)", "Compute Instance Groups", "OCI Functions", "On-Premises Windows Servers directly"]'::jsonb, '[3]'::jsonb, 'On-Premises Windows Servers directly', 'medium'),
    (s, 'mcq', 'What deployment strategy updates instances incrementally in groups to ensure zero downtime?', '["Blue-Green Deployment", "Rolling Deployment", "Canary Deployment", "Big Bang Deployment"]'::jsonb, '[1]'::jsonb, 'Rolling Deployment', 'hard'),
    (s, 'mcq', 'What OCI DevOps resource defines where the application is deployed?', '["Deploy Pipeline", "Deploy Environment", "Deploy Stage", "Deploy Artifact"]'::jsonb, '[1]'::jsonb, 'Deploy Environment', 'easy'),
    (s, 'mcq', 'How can you enforce manual verification before code is released to production in a deploy pipeline?', '["Add an Approval Stage to the deployment pipeline", "Configure a network firewall block", "Write custom bash sleep loops", "Use dynamic group access rules only"]'::jsonb, '[0]'::jsonb, 'Add an Approval Stage to the deployment pipeline', 'easy'),
    (s, 'mcq', 'What is the role of a deployment manifest in OCI DevOps?', '["It holds the billing history of the DevOps project.", "It contains instructions for configuring the destination environment (e.g. Kubernetes spec).", "It specifies the source code repository URL.", "It lists the users who have access to the project."]'::jsonb, '[1]'::jsonb, 'It contains instructions for configuring the destination environment.', 'medium');
  INSERT INTO public.subtopics (course_id, name, order_index) VALUES (c5, 'Integration and Triggers', 4) RETURNING id INTO s;
  INSERT INTO public.questions (subtopic_id, type, question_text, options, correct_answers, explanation, difficulty) VALUES
    (s, 'mcq', 'Which OCI service can be integrated with DevOps to notify developers about pipeline failure?', '["OCI Vault", "OCI Notifications (ONS)", "OCI File Storage", "OCI Block Volume"]'::jsonb, '[1]'::jsonb, 'OCI Notifications (ONS)', 'easy'),
    (s, 'mcq', 'What filter configuration can prevent a build pipeline from triggering on every commit?', '["Branch and file path filters in the trigger definition", "VCN security list modifications", "User password restrictions", "Deleting the code repository"]'::jsonb, '[0]'::jsonb, 'Branch and file path filters in the trigger definition', 'medium'),
    (s, 'mcq', 'Can OCI DevOps trigger deployments based on new images pushed to the OCI Container Registry?', '["No, it only supports source code commits.", "Yes, using triggers configured for Container Registry events.", "Only when using GoldenGate replication.", "Yes, but only for AMD-based container images."]'::jsonb, '[1]'::jsonb, 'Yes, using triggers configured for Container Registry events.', 'medium'),
    (s, 'mcq', 'Which encryption service is used to secure parameters and access tokens in OCI DevOps build steps?', '["OCI Vault", "OCI Certificates", "OCI Cloud Guard", "Standard database encryption"]'::jsonb, '[0]'::jsonb, 'OCI Vault', 'easy'),
    (s, 'mcq', 'What is a trigger payload in the context of OCI DevOps?', '["The payment information sent to Oracle.", "The metadata containing commit details sent by Git providers.", "The binary file uploaded to the registry.", "The network security rules definition."]'::jsonb, '[1]'::jsonb, 'The metadata containing commit details sent by Git providers.', 'medium');
  INSERT INTO public.subtopics (course_id, name, order_index) VALUES (c5, 'Monitoring and Best Practices', 5) RETURNING id INTO s;
  INSERT INTO public.questions (subtopic_id, type, question_text, options, correct_answers, explanation, difficulty) VALUES
    (s, 'mcq', 'Where can you view execution logs for build pipeline stages?', '["In the OCI Database console", "Directly in the Build Run History page of OCI DevOps", "In the local browser''s cache only", "In the Object Storage archive bucket only"]'::jsonb, '[1]'::jsonb, 'Directly in the Build Run History page of OCI DevOps', 'easy'),
    (s, 'mcq', 'What is the best practice for storing Git passwords or GitHub personal access tokens for OCI DevOps integrations?', '["Write them in plain text in the buildspec.yaml.", "Store them as Secrets in the OCI Vault.", "Save them in a public Object Storage bucket.", "Hardcode them inside the application source code."]'::jsonb, '[1]'::jsonb, 'Store them as Secrets in the OCI Vault.', 'easy'),
    (s, 'mcq', 'Which OCI service is used to audit administrative changes made to OCI DevOps resources?', '["OCI Logging", "OCI Audit", "OCI Monitoring", "OCI Security Zones"]'::jsonb, '[1]'::jsonb, 'OCI Audit', 'medium'),
    (s, 'mcq', 'Why is it recommended to separate build pipelines from deployment pipelines?', '["Because build pipelines are paid and deploy pipelines are free.", "To isolate environment-specific secrets and ensure a build artifact can be deployed across multiple environments without rebuilding.", "Because OCI does not support running them in the same region.", "To prevent Git repositories from getting too large."]'::jsonb, '[1]'::jsonb, 'To isolate environment-specific secrets and ensure a build artifact can be deployed across multiple environments without rebuilding.', 'medium'),
    (s, 'mcq', 'What mechanism ensures only authenticated committers can trigger builds?', '["Webhook secret validation", "Disabling internet gateways", "Using only private subnets for code repositories", "Manually approving every commit via email"]'::jsonb, '[0]'::jsonb, 'Webhook secret validation', 'medium');
  INSERT INTO public.courses (name, description, icon) VALUES
    ('Oracle Fusion Cloud Applications PaaS', 'Comprehensive prep covering Fusion Cloud extensibility, Integration Cloud, Business Intelligence, Security Console, and Data Loaders.', 'cpu')
  INSERT INTO public.subtopics (course_id, name, order_index) VALUES (c6, 'Fusion Cloud Architecture and Extensibility', 1) RETURNING id INTO s;
  INSERT INTO public.questions (subtopic_id, type, question_text, options, correct_answers, explanation, difficulty) VALUES
    (s, 'mcq', 'What is the primary tool used to customize and extend the user interface of Oracle Fusion Cloud Applications?', '["Page Composer", "SQL Worksheet", "APEX Console", "BI Publisher"]'::jsonb, '[0]'::jsonb, 'Page Composer is the primary tool for UI customizations in Fusion Applications.', 'easy'),
    (s, 'mcq', 'Which framework is used to build standard Oracle Fusion Cloud UI components?', '["React", "Oracle Application Development Framework (ADF)", "Angular", "Vue.js"]'::jsonb, '[1]'::jsonb, 'Oracle ADF is the underlying framework for Fusion Cloud UIs.', 'medium'),
    (s, 'mcq', 'What is the purpose of Sandbox in Oracle Fusion Cloud Applications?', '["To test network firewall rules.", "To isolate UI and data model customizations before publishing them to all users.", "To run high-performance SQL queries.", "To back up the production database."]'::jsonb, '[1]'::jsonb, 'Sandboxes provide an isolated environment to develop and test customizations before making them public.', 'easy'),
    (s, 'mcq', 'Which type of flexfield allows customers to add custom attributes to Fusion application tables without writing code?', '["Descriptive Flexfields (DFF)", "Key Flexfields (KFF)", "System Flexfields", "None of these"]'::jsonb, '[0]'::jsonb, 'Descriptive Flexfields (DFFs) are used to capture additional tracking attributes on standard pages.', 'medium'),
    (s, 'mcq', 'Which tool is used to manage and configure Oracle Fusion Cloud applications setup data using worksheets and import/export processes?', '["Functional Setup Manager (FSM)", "Page Composer", "Security Console", "BI Publisher"]'::jsonb, '[0]'::jsonb, 'Functional Setup Manager (FSM) manages application configuration lifecycle.', 'medium'),
    (s, 'mcq', 'Which flexfield type is primarily used to represent core structure configurations like the Chart of Accounts?', '["Descriptive Flexfield (DFF)", "Key Flexfield (KFF)", "Extensible Flexfield (EFF)", "Contextual Flexfield"]'::jsonb, '[1]'::jsonb, 'Key Flexfields (KFF) are used for structured keys like Chart of Accounts.', 'medium'),
    (s, 'mcq', 'In Fusion Applications, what does the term "Extensible Flexfield (EFF)" offer over standard DFFs?', '["They are faster to compile.", "They support one-to-many relationships and grouping attributes into separate contexts.", "They can only be configured by Oracle support.", "They do not store data in the database."]'::jsonb, '[1]'::jsonb, 'EFFs allow grouping multiple attributes into contexts and support multiple rows of custom attributes.', 'hard'),
    (s, 'mcq', 'What is the primary way to migrate configurations from a Test environment to a Production environment in Fusion Cloud?', '["Configuration Packages in Functional Setup Manager (FSM)", "Copying database tables directly", "Manually re-entering all settings", "Using SQL Developer schema sync"]'::jsonb, '[0]'::jsonb, 'FSM Configuration Packages are used to export and import setup configurations.', 'medium'),
    (s, 'mcq', 'What mechanism does Fusion Applications use to display custom fields depending on the value of a controlling field?', '["Context-sensitive flexfields", "Global flexfields", "Key flexfields", "Lookup codes only"]'::jsonb, '[0]'::jsonb, 'Context-sensitive descriptive flexfields render fields based on the selected context segment value.', 'medium'),
    (s, 'mcq', 'Which repository stores ADF customizations and personalization details in Fusion Cloud Applications?', '["Metadata Services (MDS) Repository", "Identity Store", "Policy Store", "WebLogic Temp folder"]'::jsonb, '[0]'::jsonb, 'MDS (Metadata Services) is the standard repository for storing ADF custom metadata layers.', 'hard');
  INSERT INTO public.subtopics (course_id, name, order_index) VALUES (c6, 'Business Intelligence and Reporting', 2) RETURNING id INTO s;
  INSERT INTO public.questions (subtopic_id, type, question_text, options, correct_answers, explanation, difficulty) VALUES
    (s, 'mcq', 'Which tool is best suited for designing highly formatted operational documents, such as invoices or purchase orders, in Fusion Cloud?', '["BI Publisher", "OTBI (Oracle Transactional Business Intelligence)", "Page Composer", "Smart View"]'::jsonb, '[0]'::jsonb, 'BI Publisher is used for highly formatted, pixel-perfect documents.', 'easy'),
    (s, 'mcq', 'What is a key difference between OTBI and BI Publisher?', '["OTBI queries the transactional database in real-time using logical subject areas, while BI Publisher can run direct SQL queries.", "BI Publisher is real-time, while OTBI is always delayed.", "OTBI requires complex data warehouse pipelines, while BI Publisher does not.", "OTBI can only write data to the database."]'::jsonb, '[0]'::jsonb, 'OTBI uses logical Subject Areas for real-time reporting, while BI Publisher uses Data Models that can include direct SQL.', 'medium'),
    (s, 'mcq', 'Which technology enables business users to build ad-hoc analyses using drag-and-drop subject areas in Fusion Cloud?', '["OTBI", "BI Publisher SQL", "Oracle Data Integrator", "ESS Job console"]'::jsonb, '[0]'::jsonb, 'OTBI provides logical subject areas for drag-and-drop business analytics.', 'easy'),
    (s, 'mcq', 'Which tool allows users to run Excel-based ad-hoc queries against Fusion transactional databases and balances?', '["Smart View", "BI Publisher", "Page Composer", "Functional Setup Manager"]'::jsonb, '[0]'::jsonb, 'Smart View is the Microsoft Office interface for Oracle Cloud EPM and ERP.', 'medium'),
    (s, 'mcq', 'What scheduling mechanism is used to run long-running reports or integration jobs in Oracle Fusion?', '["Enterprise Scheduler Service (ESS) Jobs", "Database cron jobs", "Linux systemctl timers", "WebLogic Scheduler Console"]'::jsonb, '[0]'::jsonb, 'ESS Jobs are used to run and monitor background processes and reports.', 'easy'),
    (s, 'mcq', 'In OTBI, how are custom calculations or custom columns created in an analysis?', '["Using Logical SQL formulas in the Criteria tab", "By modifying the underlying database tables", "By writing custom Java classes", "By creating new descriptive flexfields"]'::jsonb, '[0]'::jsonb, 'You can add formulas to columns in the Criteria tab of OTBI.', 'medium'),
    (s, 'mcq', 'Which format is NOT natively supported as an output template in BI Publisher?', '["RTF", "PDF", "Excel", "ZIP archive of raw database blocks"]'::jsonb, '[3]'::jsonb, 'ZIP archive is not a supported reporting template.', 'easy'),
    (s, 'mcq', 'What is the purpose of BI Publisher Data Models?', '["To define the dataset query, structure, parameters, and triggers for a report.", "To store the UI layout of the report.", "To authenticate users.", "To define VCN network rules."]'::jsonb, '[0]'::jsonb, 'A Data Model defines where and how data is fetched for the report templates to consume.', 'medium'),
    (s, 'mcq', 'How can you protect a BI Publisher report so that only authorized users can view its output?', '["By setting folder-level permissions in the BI Catalog and securing the data model", "By disabling the database port", "By using only stateless security rules", "By hiding the report name from search"]'::jsonb, '[0]'::jsonb, 'Catalog folder security controls access to reports, dashboards, and data models.', 'medium'),
    (s, 'mcq', 'In OTBI, what represents the logical collections of attributes, measures, and folders representing a business area?', '["Subject Areas", "Database Views", "Data Models", "ESS Schedules"]'::jsonb, '[0]'::jsonb, 'Subject Areas group business objects logically for OTBI drag-and-drop reporting.', 'easy');
  INSERT INTO public.subtopics (course_id, name, order_index) VALUES (c6, 'Integration Cloud and Web Services', 3) RETURNING id INTO s;
  INSERT INTO public.questions (subtopic_id, type, question_text, options, correct_answers, explanation, difficulty) VALUES
    (s, 'mcq', 'Which middleware service is Oracle''s recommended platform for integrating Fusion Cloud with other cloud or on-premises systems?', '["Oracle Integration Cloud (OIC)", "Oracle GoldenGate only", "OCI DevOps Pipelines", "OCI File Storage"]'::jsonb, '[0]'::jsonb, 'OIC is the standard PaaS offering for Fusion Cloud integrations.', 'easy'),
    (s, 'mcq', 'Which type of web service uses SOAP protocols and WSDL definitions in Fusion Cloud?', '["SOAP Web Services", "REST APIs", "RSS Feeds", "Atom Feeds"]'::jsonb, '[0]'::jsonb, 'SOAP web services use WSDL and SOAP envelopes for enterprise messaging.', 'easy'),
    (s, 'mcq', 'What format is primarily used for payloads in Fusion Cloud REST APIs?', '["XML", "JSON", "CSV", "YAML"]'::jsonb, '[1]'::jsonb, 'Fusion REST APIs primarily use JSON format.', 'easy'),
    (s, 'mcq', 'What feature in Fusion Applications allows sending outbound messages to external systems automatically when a specific business event occurs?', '["Business Events and Webhooks/OIC integrations", "Database triggers", "BI Publisher FTP schedules", "Page Composer rules"]'::jsonb, '[0]'::jsonb, 'Business Events can publish events that trigger OIC integrations or webhooks.', 'medium'),
    (s, 'mcq', 'What is the purpose of the OIC Connectivity Agent?', '["To route internet traffic.", "To enable communication between Oracle Integration Cloud and on-premises applications behind firewalls.", "To compile buildspec YAML files.", "To check database security rules."]'::jsonb, '[1]'::jsonb, 'The OIC connectivity agent bridges the gap between OIC and on-premises endpoints safely.', 'medium'),
    (s, 'mcq', 'Which web service protocol is typically more lightweight and stateless for web integration?', '["SOAP", "REST", "WSDL", "FTP"]'::jsonb, '[1]'::jsonb, 'REST is standard, lightweight, and stateless compared to SOAP.', 'easy'),
    (s, 'mcq', 'What security token standard is commonly used to authorize REST APIs in Fusion Cloud without sharing passwords?', '["OAuth 2.0", "HTTP Basic Authentication", "SAML 1.0", "FTP keys"]'::jsonb, '[0]'::jsonb, 'OAuth 2.0 is the modern standard for secure token-based authorization.', 'medium'),
    (s, 'mcq', 'Which tool in OIC is used to map source data elements to target data elements visually?', '["Data Mapper", "Page Composer", "Security Console", "FSM Package Creator"]'::jsonb, '[0]'::jsonb, 'The visual Mapper tool inside OIC is used to design mappings between APIs.', 'easy'),
    (s, 'mcq', 'In OIC, what is the difference between an Orchestrated Integration and a Basic Routing Integration?', '["Orchestrated integrations support complex loops, branches, and multiple system calls, whereas Basic routing only supports simple source-to-target routes.", "Basic routing is paid and Orchestration is free.", "Basic routing runs in the database, Orchestration runs on Kubernetes.", "There is no difference."]'::jsonb, '[0]'::jsonb, 'Orchestration supports advanced flow structures, conditional branches, loops, and parallel paths.', 'medium'),
    (s, 'mcq', 'Which API or feed in Fusion Applications is used to retrieve incremental updates for synchronization purposes?', '["Atom Feeds", "SOAP WSDL descriptions", "Page Composer layouts", "ESS Job logs"]'::jsonb, '[0]'::jsonb, 'Atom Feeds are used to syndicate incremental change events (e.g. employee hires).', 'hard');
  INSERT INTO public.subtopics (course_id, name, order_index) VALUES (c6, 'Security and Security Console', 4) RETURNING id INTO s;
  INSERT INTO public.questions (subtopic_id, type, question_text, options, correct_answers, explanation, difficulty) VALUES
    (s, 'mcq', 'Which administrative area is used to manage user accounts, roles, and certificates in Fusion Applications?', '["Security Console", "Functional Setup Manager", "BI Catalog", "Page Composer"]'::jsonb, '[0]'::jsonb, 'Security Console is the central portal for managing application security.', 'easy'),
    (s, 'mcq', 'Which role type in Fusion Cloud RBAC defines a job function or business responsibility assigned to a user?', '["Job Role", "Duty Role", "Data Role", "Abstract Role"]'::jsonb, '[0]'::jsonb, 'Job Roles represent the job functions users perform in the organization.', 'medium'),
    (s, 'mcq', 'Which role type represents a set of tasks or functions required to perform a job, and is typically inherited by Job Roles?', '["Duty Role", "Abstract Role", "Data Role", "System Role"]'::jsonb, '[0]'::jsonb, 'Duty Roles define the duties/actions and are inherited by Job Roles.', 'medium'),
    (s, 'mcq', 'Which role type represents common tasks not specific to any job, such as "Employee" or "Line Manager"?', '["Abstract Role", "Job Role", "Duty Role", "Data Role"]'::jsonb, '[0]'::jsonb, 'Abstract Roles are shared roles that apply to broad categories of employees.', 'medium'),
    (s, 'mcq', 'How do you grant access to specific data records (e.g. a specific business unit) to a user in Fusion Cloud?', '["By configuring Data Security Policies or assigning Data Roles / Security Profiles", "By modifying the page UI layout", "By changing the VCN routing table", "By creating new descriptive flexfields"]'::jsonb, '[0]'::jsonb, 'Data security policies and security profiles bind users to specific organizational data scopes.', 'hard'),
    (s, 'mcq', 'Where can you generate or import SSH keys and SSL certificates for secure FTP transfer in Fusion Cloud?', '["Security Console -> Certificates tab", "Functional Setup Manager", "BI Publisher Admin page", "Compute instance details page"]'::jsonb, '[0]'::jsonb, 'The Certificates tab in Security Console handles key/certificate stores.', 'medium'),
    (s, 'mcq', 'What is a "Duty Role" in Fusion Cloud Security?', '["A role that is assigned directly to users to pay taxes.", "A collection of privileges that defines a specific task or duty within an application.", "An administrative role for managing databases.", "A role that holds VCN security lists."]'::jsonb, '[1]'::jsonb, 'Duty roles group logical privileges and are inherited by job or abstract roles.', 'medium'),
    (s, 'mcq', 'In Fusion security, what is the function of the "User Category" feature?', '["To group users for billing purposes.", "To customize login, password policies, and notification settings for different types of users (e.g., employees vs. contractors).", "To assign regional subnets.", "To grant database access."]'::jsonb, '[1]'::jsonb, 'User Categories allow defining custom password requirements and SSO settings for groups of users.', 'hard'),
    (s, 'mcq', 'Which tool or report is used to identify segregation of duties (SoD) conflicts in Fusion Cloud?', '["Security Console Role Copy and Security Reports", "OTBI SQL Editor", "APEX builder", "Service Gateway log analyzer"]'::jsonb, '[0]'::jsonb, 'Security Reports and role analysis tools in the Security Console help audit roles.', 'hard'),
    (s, 'mcq', 'Which security policy defines the actions (e.g., view, edit) a user can perform on a specific UI page or business object?', '["Function Security Policy", "Data Security Policy", "IP whitelist policy", "Network Security Group rules"]'::jsonb, '[0]'::jsonb, 'Function security defines access to features, pages, menus, and actions.', 'hard');
  INSERT INTO public.subtopics (course_id, name, order_index) VALUES (c6, 'Data Migration and Loading', 5) RETURNING id INTO s;
  INSERT INTO public.questions (subtopic_id, type, question_text, options, correct_answers, explanation, difficulty) VALUES
    (s, 'mcq', 'Which loader tool is the primary utility for bulk importing data into Oracle HCM Cloud?', '["HCM Data Loader (HDL)", "FBDI (File-Based Data Import)", "SQL*Loader", "APEX Import Utility"]'::jsonb, '[0]'::jsonb, 'HCM Data Loader (HDL) is the primary bulk loader for HCM Cloud.', 'easy'),
    (s, 'mcq', 'Which loader tool is used for bulk importing transactional data into Oracle ERP Cloud (e.g., invoices, journals)?', '["FBDI (File-Based Data Import)", "HDL", "Spreadsheet Loader", "Data Pump"]'::jsonb, '[0]'::jsonb, 'FBDI is the standard utility for loading bulk data into ERP Cloud.', 'easy'),
    (s, 'mcq', 'What format is used to represent data in FBDI templates before they are compressed into a ZIP file?', '["CSV", "JSON", "XML", "YAML"]'::jsonb, '[0]'::jsonb, 'FBDI templates generate CSV files which are zipped for upload.', 'easy'),
    (s, 'mcq', 'Which tool is best suited for business users to load smaller volumes of spreadsheet data directly from Microsoft Excel into Fusion Applications?', '["ADF Desktop Integration (ADFdi)", "HDL", "FBDI", "Data Pump"]'::jsonb, '[0]'::jsonb, 'ADFdi integrates Excel directly with Fusion application pages for real-time loading.', 'medium'),
    (s, 'mcq', 'What is the role of WebCenter Content (UCM) in data migration for Fusion Cloud?', '["To store configuration packages.", "To serve as the secure repository where files are uploaded before running import jobs.", "To act as a database backup engine.", "To monitor network traffic."]'::jsonb, '[1]'::jsonb, 'UCM (Universal Content Management) is the storage area for files used in migrations.', 'medium'),
    (s, 'mcq', 'What is the file extension of the data files uploaded to HCM Data Loader?', '[".dat", ".csv", ".json", ".xml"]'::jsonb, '[0]'::jsonb, 'HDL files use the `.dat` file extension.', 'easy'),
    (s, 'mcq', 'In FBDI, what is the purpose of the "Load Interface File for Import" ESS job?', '["To load data from the uploaded ZIP/CSV files into the staging interface tables.", "To move data from interface tables to final application tables.", "To export data from Fusion to Excel.", "To delete old audit logs."]'::jsonb, '[0]'::jsonb, 'The load interface job parses CSV files and writes them to interface staging tables.', 'medium'),
    (s, 'mcq', 'In data loading, what is the difference between the staging interface tables and the application tables?', '["Interface tables hold raw uploaded data for validation, while application tables store the verified production data.", "Interface tables are free, application tables are paid.", "Interface tables are stored in Object Storage, application tables are in the database.", "There is no difference."]'::jsonb, '[0]'::jsonb, 'Interface tables act as a temporary landing zone for data verification and cleaning before final import.', 'medium'),
    (s, 'mcq', 'Which tool provides web-based spreadsheet loaders for quick HCM setups (like departments or locations)?', '["HCM Spreadsheet Data Loader (HSDL)", "FBDI", "SQL*Loader", "Data Integrator"]'::jsonb, '[0]'::jsonb, 'HSDL enables spreadsheet-based data loading tailored for business users.', 'medium'),
    (s, 'mcq', 'What is the standard encryption mechanism supported for secure file transfers to WebCenter Content (UCM)?', '["PGP Encryption", "DES Encryption", "WEP Encryption", "MD5 hashing only"]'::jsonb, '[0]'::jsonb, 'Pretty Good Privacy (PGP) encryption is standard for secure data exchanges with Fusion Cloud.', 'hard');
